    font: inherit;
    background: var(--elevated);
    color: var(--ink);
}

.reveal>* {
    animation: fade-in-up 420ms ease both;
}

.reveal>*:nth-child(2) {
    animation-delay: 70ms;
}

.reveal>*:nth-child(3) {
    animation-delay: 140ms;
}

@keyframes fade-in-up {
    from {
        opacity: 0;
        transform: translateY(10px);
    }

    to {
        opacity: 1;
        transform: translateY(0);
    }
}

.hamburger {
    display: none;
    flex-direction: column;
    justify-content: center;
    gap: 5px;
    background: none;
    border: none;
    cursor: pointer;
    padding: 0.4rem;
    margin-left: auto;
}

.ham-bar {
    display: block;
    width: 22px;
    height: 2px;
    background: var(--ink);
    border-radius: 2px;
    transition: transform 200ms ease, opacity 200ms ease;
}

@media (max-width: 700px) {

    .hamburger {
        display: flex;
    }

    /* Keep "Join Discord" visible on mobile (key call-to-action); drop the TV Mode toggle,
       which is only useful on an in-store display, to make room. */
    .tv-toggle {
        display: none;
    }

    .nav-row {
        display: none;
        border-top: none;
    }

    .nav-row.nav-open {
        display: block;
        border-top: 1px solid var(--line);
    }

    .nav-inner {
        flex-direction: column;
        align-items: stretch;
        gap: 0;
        padding: 0.5rem 0;
    }

    .nav-link {
        padding: 0.75rem 1rem;
        border-radius: 0;
        border-bottom: 1px solid var(--line);
        font-size: 1rem;
    }

    .nav-link:last-child {
        border-bottom: none;
    }

    .brand {
        flex: 0 0 auto;
    }

    /* Mobile: logo only — drop the wordmark so it never wraps or crowds the bar. */
    .brand span {
        display: none;
    }
}

@media (max-width: 900px) {

    .hero-split,
    .showcase-grid,
    .hero-stats,
    .two-col,
    .three-col,
    .footer-grid {
        grid-template-columns: 1fr;
    }

    .brand {
        width: 100%;
    }

    .consignment-section-heading {
        align-items: start;
        flex-direction: column;
    }

    @media (max-width: 700px) {
        .brand {
