    border-radius: 12px;
}

.shop-skeleton-pill {
    width: 6.5rem;
    height: 2.1rem;
    border-radius: 999px;
}

.shop-skeleton-image {
    width: 100%;
    aspect-ratio: 4 / 5;
    border-radius: 0;
}

.shop-skeleton-line {
    height: 0.85rem;
    border-radius: 999px;
}

.shop-skeleton-line-short {
    width: 60%;
}

.shop-skeleton-price {
    width: 4rem;
    height: 0.95rem;
}

.shop-skeleton-badge {
    width: 4.5rem;
    height: 1.3rem;
    border-radius: 999px;
}

.shop-tile {
    display: grid;
    grid-template-rows: auto 1fr;
    min-width: 0;
    border: 1px solid var(--line);
    border-radius: 14px;
    overflow: hidden;
    background: linear-gradient(180deg, rgba(255, 255, 255, 0.02), rgba(255, 255, 255, 0)), var(--elevated);
    min-height: 100%;
    box-shadow: 0 8px 18px rgba(0, 0, 0, 0.22);
}

.shop-tile-action {
    cursor: pointer;
    transition: transform 140ms ease, box-shadow 180ms ease, border-color 180ms ease, background 180ms ease;
}

.shop-tile-action:hover,
.shop-tile-action:focus-visible {
    transform: translateY(-2px);
    box-shadow: 0 16px 28px rgba(0, 0, 0, 0.45);
    border-color: rgba(212, 175, 55, 0.28);
    background: linear-gradient(180deg, rgba(212, 175, 55, 0.04), rgba(255, 255, 255, 0)), var(--elevated);
}

.shop-tile-action:focus-visible {
    outline: 2px solid var(--ring);
    outline-offset: 2px;
}

.shop-tile-image-wrap {
    position: relative;
    width: 100%;
    aspect-ratio: 3 / 4;
    border-bottom: 1px solid var(--line);
    background: rgba(255, 255, 255, 0.03);
    overflow: hidden;
}

.shop-tile-image {
    width: 100%;
    height: 100%;
    object-fit: contain;
    padding: 0.4rem;
}

.shop-tile-image-placeholder {
    display: grid;
    place-items: center;
    width: 100%;
    height: 100%;
    color: var(--muted);
    font-size: 0.84rem;
    letter-spacing: 0.05em;
    text-transform: uppercase;
}

.shop-tile-body {
    display: grid;
    gap: 0.45rem;
    padding: 0.8rem;
}

.shop-tile-name {
    margin: 0;
    font-size: 1rem;
    font-weight: 700;
    line-height: 1.35;
    min-height: 2.7em;
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
    overflow-wrap: anywhere;
}

.shop-tile-body {
    min-width: 0;
}

.shop-item-category {
    margin: 0;
    color: var(--muted);
    font-size: 0.78rem;
    letter-spacing: 0.02em;
}

/* Set name under a single's title on the shop tile. */
.shop-tile-set {
    margin: 0;
    color: var(--ink-secondary);
    font-size: 0.78rem;
}

/* Compact the tiles at the 2-up mobile size so more fits on screen and text stays readable. */
@media (max-width: 559px) {
    .shop-tile-body {
        padding: 0.55rem;
        gap: 0.28rem;
    }
    .shop-tile-name {
        font-size: 0.82rem;
        line-height: 1.25;
        min-height: 2.05em;
    }
    .shop-tile-set,
    .shop-item-category {
        font-size: 0.7rem;
    }
    .shop-tile-image {
        padding: 0.2rem;
    }
    /* The whole tile is tappable, so the redundant "View page →" link just wastes height on mobile. */
    .shop-tile-permalink {
        display: none;
    }
    .shop-tile-price {
        font-size: 0.9rem;
    }
}

/* Vendor logo upload/preview (marketplace apply form + portal). */
.mkt-logo-editor {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-top: 12px;
    flex-wrap: wrap;
}
.mkt-logo-preview {
    width: 72px;
    height: 72px;
    object-fit: contain;
    border-radius: 10px;
    background: #000;
    padding: 4px;
    border: 1px solid rgba(255, 255, 255, 0.15);
}
.mkt-game-select {
    width: 100%;
    padding: 10px 12px;
    border-radius: 10px;
    background: var(--elevated, #16161a);
    color: inherit;
    border: 1px solid rgba(255, 255, 255, 0.15);
    font-size: 0.95rem;
}
.mkt-logo-placeholder {
    width: 72px;
    height: 72px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 10px;
    border: 1px dashed rgba(255, 255, 255, 0.25);
    color: var(--muted);
    font-size: 0.72rem;
    text-align: center;
    padding: 4px;
}
.mkt-logo-upload {
    cursor: pointer;
}
.mkt-fulfillment {
    display: flex;
    flex-wrap: wrap;
    gap: 6px 14px;
    align-items: center;
    margin-top: 10px;
    font-size: 0.85rem;
}
.mkt-fulfillment label {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    cursor: pointer;
}
.mkt-want-add {
    display: flex;
    gap: 6px;
    align-items: center;
    margin-top: 6px;
}
.mkt-want-add input {
    width: 96px;
    padding: 4px 8px;
    border-radius: 8px;
    background: var(--elevated, #16161a);
    color: inherit;
    border: 1px solid rgba(255, 255, 255, 0.15);
    font-size: 0.8rem;
}
.mkt-dealer-toggle {
    display: flex;
    flex-wrap: wrap;
    gap: 8px 12px;
    align-items: center;
    margin: 8px 0;
    font-size: 0.9rem;
}
.mkt-dealer-actions {
    display: flex;
    gap: 6px;
    align-items: center;
    flex-wrap: wrap;
}
.mkt-specialties-editor {
    margin-top: 10px;
    font-size: 0.85rem;
}
.mkt-specialties-tags {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
    margin-top: 6px;
}
.mkt-specialty-tags {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
    margin-top: 8px;
}
.mkt-specialty-tag {
    font-size: 0.72rem;
    padding: 2px 8px;
    border-radius: 999px;
    background: rgba(212, 175, 55, 0.14);
    border: 1px solid rgba(212, 175, 55, 0.35);
    color: #e7cf86;
}
.mkt-specialty-select {
    width: auto;
    min-width: 160px;
}

/* Vendor dashboard metric tiles. */
.mkt-metrics {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(120px, 1fr));
    gap: 10px;
}
.mkt-metric {
    display: flex;
    flex-direction: column;
    gap: 2px;
    padding: 12px;
    border-radius: 10px;
    border: 1px solid rgba(255, 255, 255, 0.1);
    background: rgba(255, 255, 255, 0.02);
}
.mkt-metric-num {
    font-size: 1.4rem;
    font-weight: 700;
    color: #d4af37;
    line-height: 1.1;
}
.mkt-metric-label {
    font-size: 0.75rem;
    color: var(--muted);
}
.mkt-event-add {
    margin-top: 12px;
}
.mkt-swap-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px;
}
@media (max-width: 640px) {
    .mkt-swap-grid {
        grid-template-columns: 1fr;
    }
}
.mkt-swap-list {
    max-height: 260px;
    overflow-y: auto;
}
.mkt-swap-list .mkt-admin-info {
    cursor: pointer;
}
.mkt-hidden-badge {
    color: #d4af37;
    font-size: 0.75rem;
    font-weight: 600;
}

/* Buyer-facing vendor logo (listing offers, vendor cards, vendor page, admin review). */
.mkt-vendor-logo {
    width: 40px;
    height: 40px;
    object-fit: contain;
    border-radius: 8px;
    background: #000;
    padding: 2px;
    border: 1px solid rgba(255, 255, 255, 0.15);
    vertical-align: middle;
    flex: 0 0 auto;
}
.mkt-vendor-logo-sm {
    width: 22px;
    height: 22px;
    border-radius: 5px;
    margin-right: 6px;
}
.mkt-vendor-logo-lg {
    width: 84px;
    height: 84px;
    border-radius: 12px;
}
.mkt-vendor-head {
    display: flex;
    align-items: center;
    gap: 14px;
    flex-wrap: wrap;
}
.mkt-offer-vendor-line {
    display: inline-flex;
    align-items: center;
}
.mkt-admin-preview-banner {
    margin: 0 0 12px;
    padding: 8px 12px;
    border-radius: 8px;
    background: rgba(212, 175, 55, 0.12);
    border: 1px solid rgba(212, 175, 55, 0.4);
    font-size: 0.85rem;
}

/* Vendor Missions panel. */
.mkt-mission-head {
    margin: 16px 0 8px;
    font-size: 0.95rem;
}
.mkt-mission-grid {
    list-style: none;
    margin: 0;
    padding: 0;
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
    gap: 10px;
}
.mkt-mission-card {
    display: flex;
    gap: 10px;
    align-items: center;
    padding: 10px;
    border-radius: 10px;
    border: 1px solid rgba(255, 255, 255, 0.1);
    background: rgba(255, 255, 255, 0.02);
}
.mkt-mission-img {
    width: 44px;
    height: 62px;
    object-fit: contain;
    border-radius: 6px;
    background: #000;
    flex: 0 0 auto;
}
.mkt-mission-signal {
    margin: 4px 0 0;
    font-size: 0.8rem;
    color: #d4af37;
}
.mkt-mission-source {
    display: inline-block;
    margin-top: 4px;
    font-size: 0.8rem;
    font-weight: 600;
    color: #35c759;
    text-decoration: none;
}
.mkt-mission-source:hover {
    text-decoration: underline;
}

/* "Live Local Inventory" stats strip. */
.mkt-live-stats {
    display: flex;
    flex-wrap: wrap;
    gap: 8px 18px;
    align-items: center;
    margin: 4px 0 14px;
    font-size: 0.85rem;
    color: var(--muted);
}
.mkt-live-stat {
    display: inline-flex;
    align-items: center;
    gap: 6px;
}
.mkt-live-stat strong {
    color: #d4af37;
    font-weight: 700;
}
.mkt-live-dot {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: #35c759;
    animation: mkt-live-pulse 2s infinite;
}
@keyframes mkt-live-pulse {
    0% {
        box-shadow: 0 0 0 0 rgba(53, 199, 89, 0.5);
    }
    70% {
        box-shadow: 0 0 0 6px rgba(53, 199, 89, 0);
    }
    100% {
        box-shadow: 0 0 0 0 rgba(53, 199, 89, 0);
    }
}

.shop-tile-meta-row {
    margin-top: auto;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.45rem;
}

.shop-tile-badges {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
}

.shop-tile-price {
    margin: 0;
    font-size: 0.95rem;
    font-weight: 700;
    color: var(--ink);
}

/* Online singles promo: struck-through original + discounted price + small badge. */
.shop-price-was {
    text-decoration: line-through;
    opacity: 0.6;
    font-weight: 500;
    margin-right: 0.15rem;
}
.shop-price-now {
    color: var(--accent-hover, #b45309);
    font-weight: 800;
}
.shop-price-badge {
    display: inline-block;
    font-size: 0.62rem;
    font-weight: 700;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    color: #7a3b00;
    background: #ffe1b0;
    border-radius: 999px;
    padding: 0.05rem 0.4rem;
    vertical-align: middle;
}

.shop-qty-badge {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.2rem;
    padding: 0.2rem 0.4rem;
    border-radius: 999px;
    background: rgba(212, 175, 55, 0.12);
    border: 1px solid rgba(212, 175, 55, 0.25);
    font-size: 0.74rem;
    font-weight: 700;
    color: var(--accent-hover);
    white-space: nowrap;
    flex-shrink: 0;
}

.shop-tile-permalink {
    display: inline-block;
    margin-top: 0.5rem;
    font-size: 0.76rem;
    font-weight: 600;
    color: var(--accent);
    text-decoration: none;
}

.shop-tile-permalink:hover {
    text-decoration: underline;
}

.shop-in-cart-badge {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: 0.25rem 0.5rem;
    border-radius: 999px;
    background: rgba(159, 255, 196, 0.11);
    border: 1px solid rgba(159, 255, 196, 0.35);
    font-size: 0.72rem;
    font-weight: 700;
    color: #8ce6ac;
    white-space: nowrap;
}

.shop-in-cart-note {
    margin: 0;
    color: #8ce6ac;
    font-weight: 600;
    font-size: 0.82rem;
}

.shop-empty {
    margin: 0;
    padding: 1rem;
    border: 1px solid var(--line);
    border-radius: 12px;
    background: rgba(0, 0, 0, 0.12);
}

/* Marketplace outlet — clearly secondary to our own inventory: separated by a rule, softer framing. */
.shop-vendor-outlet {
    margin-top: 2rem;
    padding-top: 1.5rem;
    border-top: 1px solid var(--line);
}

.shop-vendor-outlet-head {
    margin-bottom: 1rem;
}

.shop-vendor-outlet-head h2 {
    margin: 0 0 0.25rem;
    font-size: 1.15rem;
}

.shop-vendor-outlet-head p {
    margin: 0;
    max-width: 60ch;
}

@media (max-width: 900px) {
    .shop-grid {
        grid-template-columns: repeat(auto-fill, minmax(190px, 1fr));
        gap: 0.85rem;
    }
    /* Keep the card-friendly 3/4 ratio (from the base rule) so full cards show, not a cropped square. */
}

@media (max-width: 640px) {
    .shop-category-mobile {
        display: grid;
    }

    .shop-category-tabs {
        display: none;
    }

    .shop-grid {
        grid-template-columns: repeat(3, minmax(0, 1fr));
        gap: 0.45rem;
    }

    /* Selects size to their widest OPTION (long set names) and can push the whole page wider than the
       screen. Force them to fill the row and shrink instead. */
    .shop-sort-control {
        display: flex;
        min-width: 0;
        max-width: 100%;
    }

    .shop-sort-select {
        flex: 1;
        min-width: 0;
        max-width: 100%;
    }

    .shop-tile-image {
        padding: 0.3rem;
    }

    .shop-tile-body {
        padding: 0.5rem;
    }

    .shop-tile-name {
        font-size: 0.8rem;
        min-height: 2.4em;
    }

    .shop-tile-price {
        font-size: 0.88rem;
    }

    .shop-qty-badge {
        font-size: 0.7rem;
        padding: 0.2rem 0.45rem;
    }

    .shop-in-cart-badge {
        font-size: 0.68rem;
        padding: 0.2rem 0.45rem;
    }

    .shop-mobile-cart-fab {
        display: inline-flex;
        position: fixed;
        right: 0.85rem;
        bottom: calc(1rem + env(safe-area-inset-bottom, 0px));
        z-index: 1400;
        align-items: center;
        justify-content: center;
        width: 3rem;
        height: 3rem;
        border-radius: 16px;
        border: 1px solid rgba(255, 255, 255, 0.16);
        background: rgba(21, 21, 21, 0.92);
        color: rgba(255, 247, 227, 0.95);
        padding: 0;
        box-shadow: 0 12px 24px rgba(0, 0, 0, 0.32);
    }

    .shop-mobile-cart-fab .shop-cart-icon-svg {
        width: 1.34rem;
        height: 1.34rem;
    }

    .shop-mobile-cart-fab .shop-cart-badge {
        top: -0.34rem;
        right: -0.34rem;
    }
}

@media (max-width: 420px) {
    .shop-grid {
        grid-template-columns: repeat(3, minmax(0, 1fr));
        gap: 0.45rem;
    }
}

.shop-detail {
    display: grid;
    gap: 0.8rem;
    border: 1px solid var(--line);
    border-radius: 16px;
    padding: 0.85rem;
    background: linear-gradient(180deg, rgba(255, 255, 255, 0.02), rgba(255, 255, 255, 0)), var(--elevated);
}

.shop-detail-viewport {
    position: fixed;
    inset: 0;
    z-index: 3200;
    height: 100svh;
    width: 100%;
    padding: 0.4rem;
    background: var(--bg);
}

.shop-detail-shell {
    width: 100%;
    height: 100%;
    margin: 0 auto;
    display: grid;
    gap: 0.38rem;
    grid-template-rows: auto minmax(0, 1fr) auto;
}

.shop-detail-head {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 0.5rem;
    min-height: 2.4rem;
    padding: 0.32rem 0.48rem;
    border: 1px solid var(--line);
    border-radius: 12px;
    background: rgba(22, 22, 22, 0.88);
}

.shop-detail-back {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border: 1px solid rgba(212, 175, 55, 0.45);
    border-radius: 999px;
    padding: 0.32rem 0.86rem;
    background: linear-gradient(135deg, rgba(212, 175, 55, 0.22), rgba(212, 175, 55, 0.12));
    color: #f6ebc6;
    font: inherit;
    font-size: 0.82rem;
    font-weight: 700;
    letter-spacing: 0.02em;
    cursor: pointer;
}

.shop-detail-counter {
    margin: 0;
    font-size: 0.75rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--ink-secondary);
    border: 1px solid var(--line);
    border-radius: 999px;
    padding: 0.22rem 0.5rem;
}

.shop-detail-stage {
    position: relative;
    min-height: min(72svh, 900px);
    border: 1px solid var(--line);
    border-radius: 14px;
    overflow: hidden;
    background: rgba(0, 0, 0, 0.22);
    display: flex;
    align-items: center;
    justify-content: center;
    padding: clamp(0.35rem, 1.2vw, 0.9rem);
    touch-action: pan-y;
}

.shop-detail-nav {
    position: absolute;
    top: 50%;
    transform: translateY(-50%);
    z-index: 2;
    min-width: 2.6rem;
    height: 2.6rem;
    border-radius: 999px;
    border: 1px solid rgba(255, 255, 255, 0.25);
    background: rgba(19, 19, 19, 0.78);
    color: var(--ink);
    font: inherit;
    font-size: 0.78rem;
    font-weight: 700;
    cursor: pointer;
}

.shop-detail-nav:hover,
.shop-detail-nav:focus-visible,
.shop-detail-back:hover,
.shop-detail-back:focus-visible {
    border-color: rgba(212, 175, 55, 0.45);
    box-shadow: 0 0 0 1px rgba(212, 175, 55, 0.3);
}

.shop-detail-nav-prev {
    left: 0.8rem;
}

.shop-detail-nav-next {
    right: 0.8rem;
}

.shop-detail-photo {
    display: block;
    width: 100%;
    height: 100%;
    max-width: 100%;
    max-height: 100%;
    object-fit: contain;
    object-position: center;
}

.shop-detail-photo-placeholder {
    width: 100%;
    min-height: 100%;
    display: grid;
    place-items: center;
    color: var(--muted);
    letter-spacing: 0.05em;
    text-transform: uppercase;
    font-size: 0.84rem;
}

.shop-detail-meta {
    display: grid;
    gap: 0.18rem;
    min-height: 2.8rem;
    padding: 0.32rem 0.52rem;
    border: 1px solid var(--line);
    border-radius: 12px;
    background: rgba(22, 22, 22, 0.9);
}

.shop-detail-meta h3,
.shop-detail-meta p {
    margin: 0;
}

.shop-detail-meta h3 {
    font-size: 0.94rem;
    line-height: 1.25;
}

.shop-detail-summary {
    font-weight: 700;
    font-size: 0.82rem;
}

.shop-detail-category {
    font-size: 0.74rem;
    line-height: 1.2;
}

.shop-payment-note {
    margin-top: 0.22rem;
    font-size: 0.72rem;
}

.shop-payment-panel {
    margin-top: 0.4rem;
    display: grid;
    gap: 0.38rem;
    padding: 0.55rem;
    border: 1px solid var(--line);
    border-radius: 10px;
    background: rgba(0, 0, 0, 0.2);
}

.cart-shipping-rates {
    margin-top: 0.6rem;
}

.cart-rate-list {
    border: 1px solid var(--line);
    border-radius: 10px;
    padding: 0.5rem 0.7rem;
    display: grid;
    gap: 0.35rem;
}

.cart-rate-list legend {
    font-size: 0.7rem;
    color: var(--ink-secondary);
    text-transform: uppercase;
    letter-spacing: 0.04em;
    padding: 0 0.3rem;
}

.cart-rate-option {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    font-size: 0.8rem;
    cursor: pointer;
    padding: 0.25rem 0.15rem;
}

.cart-rate-option .cart-rate-name {
    flex: 1;
}

.cart-rate-option strong {
    color: var(--accent);
}

.shop-payment-breakdown {
    display: grid;
    gap: 0.22rem;
}

.shop-payment-breakdown p {
    margin: 0;
    display: flex;
    justify-content: space-between;
    font-size: 0.75rem;
    color: var(--ink-secondary);
}

.shop-payment-breakdown strong {
    color: var(--ink);
}

.shop-payment-total {
    padding-top: 0.15rem;
    border-top: 1px solid var(--line);
}

.shop-payment-total strong {
    color: var(--accent);
}

.shop-payment-card {
    min-height: 58px;
    border: 1px solid rgba(255, 255, 255, 0.12);
    border-radius: 10px;
    padding: 0.5rem;
    background: rgba(255, 255, 255, 0.02);
}

.shop-payment-card-loading {
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-radius: 10px;
    padding: 0.5rem;
    background: rgba(0, 0, 0, 0.16);
}

.shop-payment-card-loading::before {
    content: "";
    display: block;
    height: 40px;
    border-radius: 8px;
    background: linear-gradient(90deg, rgba(255, 255, 255, 0.08), rgba(255, 255, 255, 0.14), rgba(255, 255, 255, 0.08));
    background-size: 200% 100%;
    animation: cart-shimmer 1.05s linear infinite;
}

.shop-payment-submit {
    gap: 0.45rem;
    width: 100%;
}

/* A disabled pay button must LOOK disabled — otherwise it reads as clickable while the form/payment
   is incomplete. Grey it out, drop the emphasis, and show a not-allowed cursor. */
.button.primary:disabled,
.button.primary[disabled],
.shop-payment-submit:disabled,
.shop-payment-submit[disabled] {
    opacity: 0.45;
    cursor: not-allowed;
    filter: grayscale(0.4);
    box-shadow: none;
    transform: none;
}

.button.primary:disabled:hover,
.shop-payment-submit:disabled:hover {
    opacity: 0.45;
    transform: none;
    box-shadow: none;
}

.shop-payment-submit-mobile {
    display: none;
}

.shop-payment-mobile-bar {
    display: none;
}

.shop-payment-mobile-meta {
    display: grid;
    gap: 0.05rem;
}

.shop-payment-mobile-total-label {
    margin: 0;
    font-size: 0.72rem;
    color: var(--ink-secondary);
    letter-spacing: 0.05em;
    text-transform: uppercase;
}

.shop-payment-mobile-total-value {
    font-size: 1rem;
    color: var(--accent-hover);
}

.shop-payment-error,
.shop-payment-success {
    margin: 0;
    font-size: 0.72rem;
}

.shop-payment-error {
    color: #f69393;
}

.shop-payment-success {
    color: #9de5a9;
}

@keyframes cart-shimmer {
    from {
        background-position: 0 0;
    }

    to {
        background-position: -200% 0;
    }
}

@keyframes cart-badge-pulse {
    0%,
    100% {
        transform: scale(0.86);
        opacity: 0.55;
    }

    50% {
        transform: scale(1);
        opacity: 0.95;
    }
}

@media (max-width: 760px) {
    .cart-checkout-card {
        gap: 0.7rem;
        padding-bottom: 0.9rem;
    }

    .cart-fulfillment-mode {
        min-height: 2.85rem;
        font-size: 0.9rem;
    }

    .cart-line-item {
        gap: 0.55rem;
        padding: 0.55rem;
    }

    .cart-line-actions {
        gap: 0.3rem;
    }

    .cart-line-actions .button {
        min-height: 2.5rem;
        min-width: 2.5rem;
        padding: 0.45rem 0.62rem;
        font-size: 0.82rem;
    }

    .shop-payment-submit-desktop {
        display: none;
    }

    .shop-payment-mobile-bar {
        position: fixed;
        left: 0.7rem;
        right: 0.7rem;
        bottom: calc(0.7rem + env(safe-area-inset-bottom, 0px));
        z-index: 1500;
        display: grid;
        grid-template-columns: minmax(0, 1fr) auto;
        align-items: center;
        gap: 0.6rem;
        padding: 0.55rem 0.6rem;
        border-radius: 14px;
        border: 1px solid rgba(255, 255, 255, 0.14);
        background: rgba(14, 14, 14, 0.96);
        box-shadow: 0 14px 26px rgba(0, 0, 0, 0.35);
    }

    .shop-payment-submit-mobile {
        display: inline-flex;
        width: auto;
        min-height: 2.8rem;
        padding: 0.5rem 1rem;
    }

    .cart-page-shell {
        padding-bottom: 6rem;
    }

    .shop-detail {
        padding: 0.7rem;
        gap: 0.65rem;
    }

    .shop-detail-head {
        min-height: 2.2rem;
        padding: 0.28rem 0.42rem;
    }

    .shop-detail-nav {
        top: auto;
        bottom: 0.6rem;
        transform: none;
        min-width: 2.6rem;
        height: 2.6rem;
        font-size: 0.75rem;
    }

    .shop-detail-nav-prev {
        left: 0.6rem;
    }

    .shop-detail-nav-next {
        right: 0.6rem;
    }

    .shop-detail-photo,
    .shop-detail-photo-placeholder {
        max-width: 100%;
        max-height: 100%;
        min-height: 0;
    }

    .shop-detail-stage {
        min-height: min(68svh, 760px);
        padding: 0.4rem;
    }

    .shop-detail-viewport {
        padding: 0.3rem;
    }

    .shop-detail-shell {
        gap: 0.32rem;
    }

    .shop-detail-meta {
        min-height: 2.55rem;
        padding: 0.28rem 0.45rem;
    }

    .shop-detail-meta h3 {
        font-size: 0.88rem;
    }

    .shop-detail-summary {
        font-size: 0.77rem;
    }

    .shop-detail-category {
        font-size: 0.7rem;
    }
}

.footer-secret-wrap {
    margin: 0.1rem 0 0;
}

.footer-secret-link {
    color: rgba(212, 175, 55, 0.2);
    text-decoration: none;
    font-size: 0.95rem;
    letter-spacing: 0.12em;
}

.footer-secret-link:hover,
.footer-secret-link:focus-visible {
    color: rgba(212, 175, 55, 0.55);
}

.giveaway-wrap {
    background:
        radial-gradient(circle at 10% 10%, rgba(212, 175, 55, 0.12), transparent 35%),
        linear-gradient(180deg, rgba(255, 255, 255, 0.015), rgba(255, 255, 255, 0)),
        var(--surface);
    border-color: rgba(212, 175, 55, 0.22);
}

.giveaway-wheel-zone {
    position: relative;
    width: min(390px, 90vw);
    margin: 1rem auto 0.8rem;
}

.giveaway-pointer {
    position: absolute;
    top: -10px;
    left: 50%;
    transform: translateX(-50%);
    width: 0;
    height: 0;
    border-left: 14px solid transparent;
    border-right: 14px solid transparent;
    border-top: 28px solid var(--accent);
    z-index: 2;
    filter: drop-shadow(0 3px 6px rgba(0, 0, 0, 0.45));
}

.giveaway-wheel {
    position: relative;
    width: 100%;
    aspect-ratio: 1;
    border-radius: 50%;
    border: 10px solid #111;
    overflow: hidden;
    box-shadow:
        inset 0 0 0 3px rgba(255, 255, 255, 0.08),
        0 18px 28px rgba(0, 0, 0, 0.55);
    transition: transform 4.3s cubic-bezier(0.2, 0.8, 0.1, 1);
}

.giveaway-wheel::after {
    content: "";
    position: absolute;
    inset: 47%;
    background: var(--bg);
    border: 3px solid rgba(212, 175, 55, 0.45);
    border-radius: 50%;
    z-index: 2;
}

.giveaway-segment-label {
    position: absolute;
    top: 50%;
    left: 50%;
    width: 48%;
    transform-origin: 0 50%;
    display: flex;
    justify-content: flex-end;
    pointer-events: none;
    z-index: 1;
}

.giveaway-segment-text {
    width: 4.4rem;
    text-align: center;
    font-size: 0.73rem;
    font-weight: 800;
    letter-spacing: 0.02em;
    color: #f5f5f5;
    text-shadow: 0 1px 2px rgba(0, 0, 0, 0.75);
    line-height: 1.15;
}

.giveaway-actions {
    display: flex;
    justify-content: center;
    margin: 0.3rem 0 0.8rem;
}

.giveaway-result {
    padding: 0.9rem 1rem;
    border-radius: 12px;
    border: 1px solid rgba(212, 175, 55, 0.28);
    background: rgba(212, 175, 55, 0.08);
}

.giveaway-result h3 {
    margin-top: 0;
}

.giveaway-prizes {
    margin-top: 0.85rem;
    display: flex;
    flex-wrap: wrap;
    gap: 0.5rem;
}

/* ------------------------------------------------------------------ */
/*  Mystery Bags                                                       */
/* ------------------------------------------------------------------ */

/* Page shell -------------------------------------------------------- */
.mb-page {
    width: 100%;
    max-width: none;
    min-width: 0;
    border-radius: 18px;
    border: 1px solid rgba(212, 175, 55, 0.3);
    background:
        radial-gradient(circle at 18% 0%, rgba(215, 175, 84, 0.18), transparent 36%),
        radial-gradient(circle at 88% 72%, rgba(166, 128, 49, 0.14), transparent 44%),
        linear-gradient(160deg, rgba(19, 16, 12, 0.98), rgba(10, 10, 9, 0.99));
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.04), 0 20px 50px rgba(0, 0, 0, 0.5);
    padding: 1.1rem;
}

body:has(.mb-page) .shell.content {
    width: 100%;
    max-width: none;
    margin: 0;
}

body:has(.mb-page) .content {
    padding-inline: clamp(0.5rem, 1vw, 1rem);
    padding-top: clamp(0.5rem, 1vw, 0.9rem);
    padding-bottom: clamp(0.75rem, 1.2vw, 1rem);
}

body:has(.mb-page) .site-footer {
    display: none;
}

/* Board ------------------------------------------------------------- */
.mb-board {
    display: grid;
    gap: 1rem;
    min-width: 0;
}

/* Header ------------------------------------------------------------ */
.mb-head {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    flex-wrap: wrap;
    gap: 0.75rem;
}

.mb-kicker {
    margin: 0;
    font-size: 0.7rem;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    color: rgba(227, 195, 118, 0.9);
}

.mb-head h1 {
    margin: 0.16rem 0 0;
    font-size: clamp(1.8rem, 5vw, 3rem);
    line-height: 1;
}

.mb-live-pill {
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    flex-shrink: 0;
    padding: 0.38rem 0.75rem;
    border-radius: 999px;
    border: 1px solid rgba(84, 223, 144, 0.55);
    background: rgba(23, 61, 40, 0.5);
    color: #d8ffe5;
    font-weight: 800;
    letter-spacing: 0.07em;
    font-size: 0.72rem;
    white-space: nowrap;
}

.mb-live-dot {
    width: 0.5rem;
    height: 0.5rem;
    border-radius: 50%;
    background: #63f4a0;
    box-shadow: 0 0 12px rgba(99, 244, 160, 0.9);
    flex-shrink: 0;
}

/* Metrics strip ----------------------------------------------------- */
/* Mobile: 2-col  |  480px+: 3-col  |  900px+: 5-col              */
.mb-metrics {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 0.6rem;
}

.mb-metric {
    padding: 0.75rem 0.85rem;
    border-radius: 12px;
    border: 1px solid rgba(214, 176, 88, 0.28);
    background: linear-gradient(180deg, rgba(46, 37, 25, 0.6), rgba(17, 15, 12, 0.85));
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.03);
}

.mb-metric p {
    margin: 0;
    color: rgba(226, 203, 154, 0.82);
    font-size: 0.65rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
}

.mb-metric strong {
    display: block;
    margin-top: 0.2rem;
    font-size: clamp(1.15rem, 2.8vw, 1.55rem);
    line-height: 1;
    color: #fff8e7;
}

/* Recent hits ------------------------------------------------------- */
.mb-recent {
    border-radius: 14px;
    border: 1px solid rgba(214, 176, 88, 0.3);
    background: linear-gradient(180deg, rgba(30, 25, 18, 0.86), rgba(12, 12, 11, 0.97));
    padding: 0.8rem;
}

.mb-recent-head {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    gap: 0.5rem;
    margin-bottom: 0.65rem;
}

.mb-recent-head h3 {
    margin: 0;
    color: rgba(231, 206, 149, 0.95);
    font-size: 0.82rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
}

.mb-recent-head p {
    margin: 0;
    font-size: 0.72rem;
    color: rgba(216, 216, 216, 0.78);
}

.mb-recent-list {
    list-style: none;
    margin: 0;
    padding: 0;
    display: grid;
    gap: 0.45rem;
}

.mb-recent-item {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto auto;
    align-items: center;
    gap: 0.5rem;
    border-radius: 10px;
    border: 1px solid rgba(212, 175, 55, 0.16);
    background: rgba(255, 255, 255, 0.02);
    padding: 0.46rem 0.58rem;
}

.mb-recent-name {
    font-weight: 700;
    font-size: 0.86rem;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.mb-recent-value {
    color: #ffd787;
    font-size: 0.92rem;
    font-weight: 900;
    white-space: nowrap;
}

.mb-recent-time {
    color: rgba(215, 215, 215, 0.72);
    font-size: 0.75rem;
    white-space: nowrap;
}

.mb-recent-empty {
    margin: 0;
    color: rgba(215, 215, 215, 0.75);
    font-size: 0.84rem;
}

/* Main area --------------------------------------------------------- */
/* Mobile: stacked  |  900px+: feature + hits side by side         */
.mb-main {
    display: grid;
    gap: 1rem;
    min-width: 0;
}

/* Featured card ----------------------------------------------------- */
.mb-feature {
    border-radius: 16px;
    border: 1px solid rgba(214, 176, 88, 0.3);
    background:
        radial-gradient(circle at 80% 10%, rgba(255, 197, 92, 0.16), transparent 44%),
        linear-gradient(165deg, rgba(17, 16, 13, 0.93), rgba(10, 10, 9, 0.98));
    padding: 1rem;
    min-width: 0;
}

/* Mobile: image above info  |  640px+: image beside info          */
.mb-feature-card {
    display: grid;
    gap: 1rem;
    animation: mb-card-in 480ms ease;
    min-width: 0;
}

.mb-feature-image {
    border-radius: 12px;
    border: 1px solid rgba(233, 198, 118, 0.4);
    background: rgba(0, 0, 0, 0.28);
    box-shadow: 0 0 24px rgba(212, 175, 55, 0.12);
    overflow: hidden;
    aspect-ratio: 5 / 7;
    max-width: 180px;
    width: 100%;
    margin: 0 auto;
}

.mb-feature-image img {
    width: 100%;
    height: 100%;
    object-fit: contain;
    display: block;
}

.mb-feature-placeholder {
    width: 100%;
    height: 100%;
    display: grid;
    place-items: center;
    font-size: 0.75rem;
    text-transform: uppercase;
    color: var(--muted);
    letter-spacing: 0.05em;
}

.mb-feature-info {
    display: grid;
    gap: 0.5rem;
    align-content: center;
    min-width: 0;
}

.mb-flag {
    margin: 0;
    color: rgba(231, 206, 149, 0.85);
    text-transform: uppercase;
    letter-spacing: 0.1em;
    font-size: 0.72rem;
}

.mb-feature-info h2 {
    margin: 0;
    font-size: clamp(1.4rem, 4.5vw, 2.8rem);
    line-height: 1.05;
}

.mb-price {
    margin: 0;
    font-size: clamp(1.8rem, 6vw, 3.6rem);
    font-weight: 900;
    line-height: 1;
    color: #ffe2a1;
    text-shadow: 0 0 22px rgba(212, 175, 55, 0.22);
}

.mb-status {
    margin: 0;
    display: inline-flex;
    width: fit-content;
    border-radius: 999px;
    border: 1px solid rgba(106, 247, 168, 0.4);
    background: rgba(23, 61, 40, 0.36);
    color: #cdf9dd;
    padding: 0.35rem 0.7rem;
    font-size: 0.75rem;
    font-weight: 800;
    letter-spacing: 0.07em;
    text-transform: uppercase;
}

/* Top hits sidebar -------------------------------------------------- */
.mb-hits {
    border-radius: 14px;
    border: 1px solid rgba(214, 176, 88, 0.26);
    background: linear-gradient(180deg, rgba(22, 21, 18, 0.95), rgba(12, 12, 11, 0.98));
    padding: 0.85rem;
    min-width: 0;
}

.mb-hits h3 {
    margin: 0 0 0.7rem;
    color: rgba(231, 206, 149, 0.9);
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
}

.mb-hits-list {
    list-style: none;
    margin: 0;
    padding: 0;
    display: grid;
    gap: 0.45rem;
    min-width: 0;
}

.mb-hit {
    display: grid;
    grid-template-columns: 2.4rem minmax(0, 1fr) auto;
    align-items: center;
    gap: 0.4rem;
    border: 1px solid rgba(212, 175, 55, 0.16);
    border-radius: 10px;
    padding: 0.5rem 0.6rem;
    background: rgba(255, 255, 255, 0.02);
    transition: border-color 200ms ease, background 200ms ease;
}

.mb-hit.is-active {
    border-color: rgba(233, 198, 118, 0.44);
    background: linear-gradient(180deg, rgba(212, 175, 55, 0.1), rgba(255, 255, 255, 0.01));
}

.mb-hit-rank {
    font-size: 0.68rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: rgba(210, 210, 210, 0.65);
}

.mb-hit-name {
    font-weight: 700;
    font-size: 0.9rem;
    line-height: 1.2;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    color: var(--ink);
}

.mb-hit-price {
    font-size: 1rem;
    color: #ffd787;
    font-weight: 900;
    white-space: nowrap;
}

/* Hot ticker -------------------------------------------------------- */
.mb-ticker {
    display: grid;
    gap: 0.3rem;
    border: 1px solid rgba(214, 176, 88, 0.26);
    border-radius: 12px;
    background: rgba(16, 14, 11, 0.88);
    padding: 0.7rem 0.9rem;
    min-width: 0;
}

.mb-ticker-label {
    display: block;
    font-size: 0.65rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    color: rgba(224, 201, 148, 0.85);
}

.mb-ticker-value {
    display: block;
    font-size: clamp(0.95rem, 2.5vw, 1.35rem);
    font-weight: 800;
    color: #fff3d2;
    line-height: 1.2;
    animation: mb-ticker-in 360ms ease;
}

.mb-ticker-total {
    display: block;
    font-size: 0.8rem;
    color: rgba(214, 214, 214, 0.85);
}

.mb-ticker-total strong {
    color: #ffd787;
}

/* Animations -------------------------------------------------------- */
@keyframes mb-card-in {
    from {
        opacity: 0;
        transform: translateY(10px);
    }

    to {
        opacity: 1;
        transform: translateY(0);
    }
}

@keyframes mb-ticker-in {
    from {
        opacity: 0;
        transform: translateY(5px);
    }

    to {
        opacity: 1;
        transform: translateY(0);
    }
}

/* 480px: 3-col metrics ---------------------------------------------- */
@media (min-width: 480px) {
    .mb-metrics {
        grid-template-columns: repeat(3, 1fr);
    }
}

/* 640px: feature card image beside info, ticker in a row ------------ */
@media (min-width: 640px) {
    .mb-feature-card {
        grid-template-columns: auto 1fr;
        align-items: center;
    }

    .mb-feature-image {
        max-width: min(150px, 38vw);
        margin: 0;
    }

    .mb-ticker {
        grid-template-columns: auto minmax(0, 1fr) auto;
        align-items: center;
    }

    .mb-ticker-total {
        text-align: right;
    }
}

/* 900px: side-by-side main panel + 5-col metrics ------------------- */
@media (min-width: 900px) {
    .mb-metrics {
        grid-template-columns: repeat(5, 1fr);
    }

    .mb-main {
        grid-template-columns: minmax(0, 1.6fr) minmax(260px, 0.7fr);
    }

    .mb-feature-image {
        max-width: min(172px, 24vw);
    }
}

/* 1200px: bigger feature image -------------------------------------- */
@media (min-width: 1200px) {
    .mb-feature-image {
        max-width: min(218px, 22vw);
    }
}

/* TV mode ----------------------------------------------------------- */
html.tv-mode .mb-board,
body.tv-mode .mb-board {
    gap: 0.65rem;
}

html.tv-mode .mb-head h1,
body.tv-mode .mb-head h1 {
    font-size: clamp(2rem, 3vw, 3.4rem);
}

html.tv-mode .mb-metric strong,
body.tv-mode .mb-metric strong {
    font-size: clamp(1rem, 1.6vw, 1.4rem);
}

html.tv-mode .mb-feature-image,
body.tv-mode .mb-feature-image {
    max-width: 188px;
}

html.tv-mode .mb-ticker-value,
body.tv-mode .mb-ticker-value {
    font-size: clamp(1rem, 1.8vw, 1.5rem);
}

/* Ã¢â€â‚¬Ã¢â€â‚¬ TV mode Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬ */

html.tv-mode,
body.tv-mode {
    height: 100%;
    overflow-y: hidden;
    overflow-x: visible;
}

/* Subtle fullscreen/TV-mode icon — de-emphasized (it's an in-store display toggle). */
.tv-toggle {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 32px;
    height: 32px;
    border-radius: 8px;
    border: 1px solid transparent;
    background: transparent;
    color: var(--muted, #b9b4c7);
    cursor: pointer;
    opacity: 0.6;
    transition: opacity 150ms ease, color 150ms ease, background 150ms ease, border-color 150ms ease;
}
.tv-toggle:hover,
.tv-toggle:focus-visible {
    opacity: 1;
    color: var(--ink);
    background: rgba(255, 255, 255, 0.05);
}
.tv-toggle-active {
    opacity: 1;
    border-color: rgba(212, 175, 55, 0.45);
    background: rgba(212, 175, 55, 0.14);
    color: var(--accent-hover);
}

html.tv-mode .shell,
body.tv-mode .shell {
    width: 100%;
    max-width: none;
    margin-inline: 0;
    padding-inline: 0.6rem;
}

html.tv-mode .site-header,
body.tv-mode .site-header {
    background: rgba(12, 12, 12, 0.96);
}

html.tv-mode .mb-page,
body.tv-mode .mb-page {
    height: calc(100svh - 5.2rem);
    overflow-y: auto;
    overscroll-behavior: contain;
    padding-right: 0.2rem;
}

/* ------------------------------------------------------------------ */
/*  Mystery Bags (Rare Cards Focused Layout)                           */
/* ------------------------------------------------------------------ */

.mb2-board {
    display: grid;
    gap: 0.95rem;
    position: relative;
}

.mb2-head {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 0.85rem;
    flex-wrap: wrap;
}

.mb2-head-copy {
    max-width: 64ch;
}

.mb2-kicker {
    margin: 0;
    color: rgba(227, 195, 118, 0.88);
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.16em;
}

.mb2-head h1 {
    margin: 0.14rem 0 0;
    font-size: clamp(1.8rem, 5vw, 3rem);
    line-height: 1;
    letter-spacing: 0.01em;
}

.mb2-subhead {
    margin: 0.5rem 0 0;
    color: rgba(236, 230, 214, 0.82);
    font-size: clamp(0.9rem, 1.7vw, 1.02rem);
    line-height: 1.45;
}

.mb2-count {
    padding: 0.4rem 0.78rem;
    border-radius: 999px;
    border: 1px solid rgba(84, 223, 144, 0.5);
    background: rgba(23, 61, 40, 0.46);
    color: #d8ffe5;
    font-size: 0.74rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    font-weight: 800;
    white-space: nowrap;
}

.mb2-stats {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(118px, 1fr));
    gap: 0.6rem;
}

.mb2-stat-card {
    display: grid;
    gap: 0.2rem;
    border: 1px solid rgba(214, 176, 88, 0.24);
    border-radius: 12px;
    padding: 0.58rem 0.7rem;
    background:
        radial-gradient(circle at 85% 2%, rgba(255, 205, 105, 0.16), transparent 48%),
        linear-gradient(160deg, rgba(27, 24, 19, 0.95), rgba(13, 12, 10, 0.96));
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.04);
}

.mb2-stat-card span {
    color: rgba(224, 201, 148, 0.76);
    text-transform: uppercase;
    font-size: 0.65rem;
    letter-spacing: 0.09em;
    font-weight: 700;
}

.mb2-stat-card strong {
    color: #ffe2a1;
    font-size: clamp(1.1rem, 2.9vw, 1.42rem);
    line-height: 1.1;
}

/* Layout: main column + QR sidebar ---------------------------------- */
.mb2-layout {
    display: grid;
    grid-template-columns: minmax(0, 1fr) 248px;
    gap: 0.95rem;
    align-items: start;
}

.mb2-main-col {
    display: grid;
    gap: 0.95rem;
    min-width: 0;
}

/* QR marketing rail ------------------------------------------------- */
.mb2-qr-rail {
    position: sticky;
    top: 0.75rem;
    display: grid;
    gap: 0.7rem;
    align-content: start;
    padding: 0.85rem;
    border: 1px solid rgba(214, 176, 88, 0.28);
    border-radius: 14px;
    background:
        radial-gradient(circle at 80% 6%, rgba(255, 197, 92, 0.16), transparent 50%),
        linear-gradient(165deg, rgba(23, 20, 15, 0.95), rgba(10, 10, 9, 0.98));
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.04);
}

.mb2-qr-rail-title {
    margin: 0;
    color: rgba(227, 195, 118, 0.9);
    text-transform: uppercase;
    letter-spacing: 0.14em;
    font-size: 0.68rem;
    font-weight: 800;
    text-align: center;
}

.mb2-qr-card {
    display: grid;
    gap: 0.65rem;
    justify-items: center;
    text-align: center;
    animation: mb2-fade-in 360ms ease;
}

.mb2-qr-code {
    width: 100%;
    max-width: 188px;
    padding: 0.6rem;
    border-radius: 12px;
    background: #ffffff;
    box-shadow: 0 8px 22px rgba(0, 0, 0, 0.38);
}

.mb2-qr-code svg {
    display: block;
    width: 100%;
    height: auto;
}

.mb2-qr-meta h3 {
    margin: 0;
    font-size: 1rem;
    line-height: 1.2;
    color: #ffe2a1;
}

.mb2-qr-meta p {
    margin: 0.22rem 0 0;
    font-size: 0.8rem;
    line-height: 1.35;
    color: rgba(236, 230, 214, 0.82);
}

.mb2-qr-dots {
    display: flex;
    justify-content: center;
    gap: 0.4rem;
}

.mb2-qr-dot {
    width: 7px;
    height: 7px;
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.26);
    transition: width 220ms ease, background-color 220ms ease;
}

.mb2-qr-dot-active {
    width: 21px;
    background: linear-gradient(90deg, #ffd98a, #ffaf6b);
}

.mb2-spotlight {
    border: 1px solid rgba(214, 176, 88, 0.28);
    border-radius: 14px;
    background:
        radial-gradient(circle at 78% 18%, rgba(255, 197, 92, 0.28), transparent 44%),
        radial-gradient(circle at 10% 88%, rgba(255, 126, 80, 0.2), transparent 42%),
        linear-gradient(160deg, rgba(23, 20, 15, 0.95), rgba(10, 10, 9, 0.98));
    padding: 0.65rem;
    min-height: 145px;
    overflow: hidden;
}

.mb2-spotlight-card {
    display: grid;
    grid-template-columns: auto 1fr;
    align-items: center;
    gap: 0.75rem;
    animation: mb2-fade-in 360ms ease;
}

.mb2-spotlight-card img {
    width: clamp(80px, 14vw, 130px);
    height: clamp(108px, 18vw, 172px);
    object-fit: contain;
    border-radius: 10px;
    border: 1px solid rgba(233, 198, 118, 0.42);
    background: rgba(0, 0, 0, 0.28);
    box-shadow: 0 0 24px rgba(212, 175, 55, 0.18);
}

.mb2-spotlight-label {
    color: rgba(224, 201, 148, 0.88);
    text-transform: uppercase;
    letter-spacing: 0.08em;
    font-size: 0.62rem;
    font-weight: 700;
    margin-bottom: 0.3rem;
}

.mb2-spotlight-meta h2,
.mb2-spotlight-meta p {
    margin: 0;
}

.mb2-spotlight-meta h2 {
    font-size: clamp(1.1rem, 3.4vw, 2rem);
    line-height: 1.1;
}

.mb2-spotlight-meta p {
    margin-top: 0.26rem;
    color: #ffe1a0;
    font-size: clamp(1.35rem, 4.6vw, 2.8rem);
    font-weight: 900;
    line-height: 1;
    text-shadow: 0 0 18px rgba(212, 175, 55, 0.24);
}

.mb2-spotlight-dots {
    display: flex;
    gap: 0.4rem;
    margin-top: 0.55rem;
}

.mb2-dot {
    width: 7px;
    height: 7px;
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.26);
}

.mb2-dot-active {
    width: 21px;
    background: linear-gradient(90deg, #ffd98a, #ffaf6b);
}

.mb2-ticker-wrap {
    border: 1px solid rgba(214, 176, 88, 0.22);
    border-radius: 999px;
    background: rgba(13, 13, 11, 0.85);
    overflow: hidden;
}

.mb2-ticker-track {
    display: inline-flex;
    gap: 1.8rem;
    white-space: nowrap;
    padding: 0.42rem 0.9rem;
    min-width: max-content;
    animation: mb2-ticker 24s linear infinite;
}

.mb2-ticker-item {
    color: rgba(240, 232, 216, 0.9);
    font-size: 0.82rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

.mb2-ticker-item strong {
    color: #ffd787;
}

.mb2-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(155px, 1fr));
    gap: 0.65rem;
}

.mb2-tile {
    border: 1px solid rgba(214, 176, 88, 0.24);
    border-radius: 12px;
    overflow: hidden;
    background:
        linear-gradient(180deg, rgba(255, 255, 255, 0.04), rgba(255, 255, 255, 0)),
        rgba(20, 18, 14, 0.95);
    box-shadow: 0 10px 22px rgba(0, 0, 0, 0.28);
    transition: transform 180ms ease, border-color 180ms ease, box-shadow 180ms ease;
}

.mb2-tile:hover {
    transform: translateY(-2px) scale(1.01);
    border-color: rgba(233, 198, 118, 0.44);
    box-shadow: 0 14px 28px rgba(0, 0, 0, 0.4), 0 0 0 1px rgba(212, 175, 55, 0.18);
}

.mb2-tile-media {
    aspect-ratio: 5 / 7;
    display: grid;
    place-items: center;
    background: rgba(0, 0, 0, 0.26);
    border-bottom: 1px solid rgba(255, 255, 255, 0.07);
}

.mb2-tile-media img {
    width: 100%;
    height: 100%;
    object-fit: contain;
    display: block;
}

.mb2-tile-placeholder {
    display: grid;
    place-items: center;
    width: 100%;
    height: 100%;
    color: var(--muted);
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.06em;
}

.mb2-tile-meta {
    padding: 0.55rem;
    display: grid;
    gap: 0.24rem;
}

.mb2-tile-meta h3,
.mb2-value,
.mb2-multiplier {
    margin: 0;
}

.mb2-tile-meta h3 {
    font-size: 0.81rem;
    line-height: 1.2;
    min-height: 2.4em;
    overflow: hidden;
}

.mb2-value {
    font-size: 1.12rem;
    font-weight: 900;
    color: #ffd787;
    line-height: 1;
}

.mb2-multiplier {
    color: rgba(216, 216, 216, 0.82);
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.06em;
}

.mb2-footer {
    display: flex;
    align-items: stretch;
    justify-content: space-between;
    gap: 0.6rem;
    border-radius: 12px;
    border: 1px solid rgba(214, 176, 88, 0.26);
    background: rgba(16, 14, 11, 0.88);
    padding: 0.62rem 0.78rem;
}

.mb2-footer-value {
    display: grid;
    gap: 0.25rem;
    align-content: center;
}

.mb2-footer span {
    text-transform: uppercase;
    letter-spacing: 0.08em;
    font-size: 0.67rem;
    color: rgba(224, 201, 148, 0.85);
}

.mb2-footer strong {
    font-size: 1.06rem;
    color: #ffe2a1;
}

.mb2-footer-actions {
    display: flex;
    align-items: center;
    gap: 0.45rem;
    flex-wrap: wrap;
    justify-content: flex-end;
}

.mb2-cta-primary,
.mb2-cta-secondary {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    text-decoration: none;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    font-size: 0.72rem;
    font-weight: 800;
    border-radius: 999px;
    padding: 0.48rem 0.8rem;
    transition: transform 180ms ease, box-shadow 180ms ease, background-color 180ms ease;
}

.mb2-cta-primary {
    color: #2f1c00;
    background: linear-gradient(135deg, #ffd585, #ffb35f);
    border: 1px solid rgba(255, 219, 147, 0.6);
}

.mb2-cta-secondary {
    color: #f0ece3;
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid rgba(255, 255, 255, 0.16);
}

.mb2-cta-primary:hover,
.mb2-cta-primary:focus-visible,
.mb2-cta-secondary:hover,
.mb2-cta-secondary:focus-visible {
    transform: translateY(-1px);
    box-shadow: 0 8px 18px rgba(0, 0, 0, 0.34);
}

@media (max-width: 960px) {
    .mb2-layout {
        grid-template-columns: 1fr;
    }

    .mb2-qr-rail {
        position: static;
        justify-items: center;
    }

    .mb2-qr-card {
        max-width: 280px;
    }
}

@media (max-width: 720px) {
    .mb2-stats {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .mb2-grid {
        grid-template-columns: repeat(auto-fill, minmax(132px, 1fr));
        gap: 0.55rem;
    }

    .mb2-spotlight-card {
        grid-template-columns: 1fr;
        justify-items: center;
        text-align: center;
        gap: 0.55rem;
    }

    .mb2-spotlight-meta h2 {
        max-width: 20ch;
    }

    .mb2-footer {
        padding: 0.55rem 0.65rem;
        flex-direction: column;
    }

    .mb2-footer-actions {
        width: 100%;
        justify-content: stretch;
    }

    .mb2-cta-primary,
    .mb2-cta-secondary {
        flex: 1;
    }
}

@media (max-width: 430px) {
    .mb2-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
}

@keyframes mb2-fade-in {
    from {
        opacity: 0;
        transform: translateY(6px);
    }

    to {
        opacity: 1;
        transform: translateY(0);
    }
}

@keyframes mb2-ticker {
    from {
        transform: translateX(0);
    }

    to {
        transform: translateX(-50%);
    }
}

html.tv-mode .top-row,
body.tv-mode .top-row {
    padding: 0.4rem 0;
    gap: 0.5rem;
}

html.tv-mode .brand,
body.tv-mode .brand {
    font-size: 1rem;
    gap: 0.45rem;
}

html.tv-mode .brand-mark,
body.tv-mode .brand-mark {
    height: 24px;
}

html.tv-mode .nav-discord,
body.tv-mode .nav-discord,
html.tv-mode .nav-row,
body.tv-mode .nav-row,
html.tv-mode .site-footer,
body.tv-mode .site-footer {
    display: none;
}

html.tv-mode .content,
body.tv-mode .content {
    padding-top: 0.55rem;
    padding-bottom: 0.6rem;
    overflow: visible;
}

html.tv-mode .reveal>*,
body.tv-mode .reveal>* {
    animation: none;
}

html.tv-mode .shop-secondary,
body.tv-mode .shop-secondary {
    display: none;
}

html.tv-mode .shop-inventory,
body.tv-mode .shop-inventory {
    gap: 0.5rem;
    margin-top: 0;
}

html.tv-mode .shop-search-row,
body.tv-mode .shop-search-row,
html.tv-mode .shop-category-tabs,
body.tv-mode .shop-category-tabs,
html.tv-mode .shop-category-mobile,
body.tv-mode .shop-category-mobile {
    display: none;
}

.shop-tv-now {
    margin: 0;
    font-size: 0.88rem;
    text-transform: uppercase;
    letter-spacing: 0.06em;
}

.shop-tv-now strong {
    color: var(--accent-hover);
}

html.tv-mode .shop-panel,
body.tv-mode .shop-panel {
    max-height: calc(100vh - 9.2rem);
    overflow: auto;
    padding-right: 0.25rem;
}

html.tv-mode .shop-grid,
body.tv-mode .shop-grid {
    grid-template-columns: repeat(auto-fill, minmax(210px, 1fr));
    gap: 0.7rem;
}

html.tv-mode .shop-tile-image-wrap,
body.tv-mode .shop-tile-image-wrap {
    aspect-ratio: 4 / 4.8;
}

html.tv-mode .shop-tile-body,
body.tv-mode .shop-tile-body {
    gap: 0.35rem;
    padding: 0.62rem;
}

html.tv-mode .shop-tile-name,
body.tv-mode .shop-tile-name {
    font-size: 0.9rem;
    min-height: 2.4em;
}

html.tv-mode .shop-tile-price,
body.tv-mode .shop-tile-price {
    font-size: 0.85rem;
}

html.tv-mode .shop-qty-badge,
body.tv-mode .shop-qty-badge {
    font-size: 0.68rem;
}

html.tv-mode .shop-in-cart-badge,
body.tv-mode .shop-in-cart-badge {
    font-size: 0.66rem;
}

html.tv-mode .shop-mobile-cart-fab,
body.tv-mode .shop-mobile-cart-fab {
    display: none;
}
@media (max-width: 700px) {

    html.tv-mode .hamburger,
    body.tv-mode .hamburger {
        display: none;
    }

    html.tv-mode .top-row,
    body.tv-mode .top-row {
        justify-content: space-between;
        flex-wrap: nowrap;
    }

    html.tv-mode .brand,
    body.tv-mode .brand {
        flex: 0 1 auto;
    }
}

/* Looking For (card wishlist) */
.lf-alert-cta {
    border: 1px solid rgba(212, 175, 55, 0.4);
    background: linear-gradient(135deg, rgba(212, 175, 55, 0.12), rgba(212, 175, 55, 0.04));
}

.lf-game-toggle {
    display: flex;
    flex-wrap: wrap;
    gap: 0.5rem;
    margin-bottom: 1rem;
}

.lf-game-active {
    background: linear-gradient(135deg, rgba(212, 175, 55, 0.28), rgba(212, 175, 55, 0.12));
    border-color: rgba(212, 175, 55, 0.5);
    color: var(--ink);
}

.lf-search-row {
    display: flex;
    flex-wrap: wrap;
    gap: 1rem;
    align-items: flex-end;
}

.lf-search-field {
    flex: 1 1 260px;
    min-width: 0;
}

.lf-search-label {
    display: block;
    margin-bottom: 0.4rem;
    color: var(--ink-secondary);
    font-size: 0.85rem;
}

.lf-search-input,
.lf-set-select {
    width: 100%;
}

.lf-set-select {
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 10px;
    padding: 0.6rem;
    font: inherit;
    background: var(--elevated);
    color: var(--ink);
}

.lf-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
    gap: 1rem;
    margin-top: 1rem;
}

.lf-card {
    display: flex;
    flex-direction: column;
    gap: 0.6rem;
    padding: 0.85rem;
    border: 1px solid var(--line);
    border-radius: 14px;
    background: rgba(255, 255, 255, 0.03);
}

.lf-card-instock {
    border-color: var(--brand-strong);
    background: rgba(212, 175, 55, 0.1);
    box-shadow: 0 0 0 1px rgba(212, 175, 55, 0.4), 0 8px 20px rgba(212, 175, 55, 0.18);
}

.lf-card-art {
    position: relative;
    display: flex;
    justify-content: center;
}

.lf-instock-badge {
    position: absolute;
    top: 0.3rem;
    left: 0.3rem;
    z-index: 1;
    padding: 0.2rem 0.5rem;
    border-radius: 999px;
    background: linear-gradient(135deg, var(--brand-strong), var(--accent-hover));
    color: #0E0E0E;
    font-size: 0.72rem;
    font-weight: 800;
    box-shadow: 0 4px 10px rgba(0, 0, 0, 0.4);
}

.lf-drawer-row-instock {
    background: rgba(212, 175, 55, 0.1);
    border-radius: 8px;
    padding-left: 0.4rem;
    padding-right: 0.4rem;
}

.lf-drawer-instock-tag {
    color: var(--accent-hover);
    font-weight: 700;
}

.lf-card-image {
    width: 100%;
    height: auto;
    max-width: 146px;
    border-radius: 8px;
}

.lf-card-image-empty {
    aspect-ratio: 146 / 204;
    background: var(--elevated);
}

.lf-card-body {
    flex: 1;
}

.lf-card-name {
    margin: 0;
    font-size: 0.95rem;
    line-height: 1.25;
}

.lf-card-meta {
    margin: 0.25rem 0 0;
    color: var(--muted);
    font-size: 0.78rem;
}

.lf-card-price {
    margin: 0.35rem 0 0;
    color: var(--accent);
    font-weight: 700;
    font-size: 0.9rem;
}

/* Quantity stepper — lets a shopper want more than one copy of the same card. */
.lf-card-actions,
.lf-drawer-actions {
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.lf-drawer-actions {
    flex: 0 0 auto;
}

.lf-qty {
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    border: 1px solid var(--line);
    border-radius: 999px;
    padding: 0.15rem 0.3rem;
    background: var(--elevated);
}

.lf-qty-btn {
    width: 1.6rem;
    height: 1.6rem;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border: none;
    border-radius: 999px;
    background: transparent;
    color: var(--accent-hover);
    font-size: 1.05rem;
    line-height: 1;
    cursor: pointer;
}

.lf-qty-btn:hover:not(:disabled) {
    background: rgba(212, 175, 55, 0.15);
}

.lf-qty-btn:disabled {
    opacity: 0.4;
    cursor: default;
}

.lf-qty-value {
    min-width: 1.4rem;
    text-align: center;
    font-weight: 700;
    font-size: 0.9rem;
}

/* Persistent "My List" access — pinned so it's reachable while scrolling a long set */
.lf-list-fab-wrap {
    position: fixed;
    right: 1rem;
    bottom: 1rem;
    z-index: 60;
    display: flex;
    flex-direction: column;
    align-items: flex-end;
    gap: 0.5rem;
}

.lf-list-fab {
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.7rem 1.1rem;
    border-radius: 999px;
    border: 1px solid rgba(212, 175, 55, 0.5);
    background: linear-gradient(135deg, var(--brand-strong), var(--accent-hover));
    color: #0E0E0E;
    font-weight: 800;
    box-shadow: 0 10px 24px rgba(0, 0, 0, 0.45);
    cursor: pointer;
}

.lf-list-hint {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    padding: 0.45rem 0.8rem;
    border-radius: 999px;
    border: 1px solid rgba(212, 175, 55, 0.5);
    background: rgba(14, 14, 14, 0.92);
    color: var(--accent-hover);
    font-weight: 700;
    font-size: 0.82rem;
    box-shadow: 0 8px 18px rgba(0, 0, 0, 0.4);
    cursor: pointer;
    animation: lf-hint-pulse 2.4s ease-in-out infinite;
}

@keyframes lf-hint-pulse {
    0%, 100% {
        transform: translateY(0);
        box-shadow: 0 8px 18px rgba(0, 0, 0, 0.4);
    }
    50% {
        transform: translateY(-3px);
        box-shadow: 0 12px 22px rgba(212, 175, 55, 0.35);
    }
}

.lf-list-fab-count {
    min-width: 1.5rem;
    height: 1.5rem;
    border-radius: 999px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: 0 0.35rem;
    background: rgba(14, 14, 14, 0.85);
    color: var(--accent-hover);
    font-size: 0.8rem;
}

.lf-drawer-overlay {
    position: fixed;
    inset: 0;
    z-index: 100;
    background: rgba(0, 0, 0, 0.6);
    display: flex;
    align-items: flex-end;
    justify-content: center;
}

.lf-drawer {
    width: 100%;
    max-width: 640px;
    max-height: 80vh;
    overflow-y: auto;
    background: var(--surface);
    border: 1px solid var(--line);
    border-radius: 16px 16px 0 0;
    padding: 1rem 1.1rem 1.5rem;
}

.lf-drawer-head {
    position: sticky;
    top: 0;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
    padding-bottom: 0.75rem;
    margin-bottom: 0.5rem;
    border-bottom: 1px solid var(--line);
    background: var(--surface);
}

.lf-drawer-head h2 {
    margin: 0;
}

.lf-drawer-alerts {
    background: rgba(212, 175, 55, 0.1);
    border: 1px solid rgba(212, 175, 55, 0.35);
    border-radius: 12px;
    padding: 0.9rem 1rem;
    margin-bottom: 1rem;
}

.lf-drawer-alerts h3 {
    margin: 0 0 0.4rem;
    color: var(--accent-hover);
}

.lf-drawer-alerts p {
    margin: 0 0 0.6rem;
    font-size: 0.9rem;
}

.lf-drawer-list {
    list-style: none;
    margin: 0;
    padding: 0;
}

.lf-drawer-row {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.6rem 0;
    border-bottom: 1px solid var(--line);
}

.lf-drawer-thumb {
    width: 40px;
    height: auto;
    border-radius: 4px;
    flex: 0 0 auto;
}

.lf-drawer-info {
    flex: 1;
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 0.1rem;
    font-size: 0.85rem;
}

.lf-drawer-info strong {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

@media (min-width: 720px) {
    .lf-drawer-overlay {
        align-items: center;
    }

    .lf-drawer {
        border-radius: 16px;
    }
}

/* "Just In" homepage call-to-action — a persistent, mobile-visible promo for fresh arrivals.
   Distinct gold-accented card so it stands apart from the regular content cards (and the banner). */
.just-in-cta {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: 1.25rem;
    border: 1px solid rgba(212, 175, 55, 0.35);
    background: linear-gradient(135deg, rgba(212, 175, 55, 0.12), rgba(212, 175, 55, 0.02)), var(--elevated);
    box-shadow: 0 10px 28px rgba(0, 0, 0, 0.28);
}

.just-in-cta-copy {
    display: grid;
    gap: 0.4rem;
    min-width: min(100%, 22rem);
    flex: 1 1 22rem;
}

.just-in-cta-copy h2 {
    margin: 0;
}

.just-in-cta-copy p:last-child {
    margin: 0;
    color: var(--ink);
    max-width: 60ch;
}

.just-in-cta-actions {
    display: flex;
    flex-wrap: wrap;
    gap: 0.6rem;
}

/* /just-in page */
.just-in-header h1 {
    margin: 0.15rem 0 0.35rem;
}

.just-in-grid {
    margin: 0;
}

.just-in-tile {
    position: relative;
}

.just-in-badge {
    position: absolute;
    top: 0.4rem;
    left: 0.4rem;
    z-index: 1;
    display: inline-flex;
    align-items: center;
    max-width: calc(100% - 0.8rem);
    white-space: nowrap;
    padding: 0.18rem 0.45rem;
    border-radius: 999px;
    background: var(--accent);
    color: #1a1a1a;
    font-size: 0.7rem;
    font-weight: 800;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    box-shadow: 0 4px 10px rgba(0, 0, 0, 0.35);
}

.just-in-badge-restock {
    background: rgba(159, 255, 196, 0.92);
    color: #103a22;
}

.just-in-time {
    color: var(--muted);
    font-size: 0.74rem;
    font-weight: 600;
    white-space: nowrap;
}

.just-in-qty {
    margin: 0.15rem 0 0;
    color: var(--accent);
    font-size: 0.78rem;
    font-weight: 700;
}

.just-in-tile-link {
    display: block;
    text-decoration: none;
    color: inherit;
}

.just-in-filters {
    display: flex;
    flex-wrap: wrap;
    gap: 1rem;
    align-items: flex-end;
}

.just-in-filters .lf-game-toggle {
    margin-bottom: 0;
}

.just-in-category {
    flex: 1 1 220px;
    min-width: 0;
}

.just-in-category .lf-set-select {
    width: 100%;
}

/* ── Vendor Marketplace ───────────────────────────────────────────────── */
.mkt-toggle-row {
    display: flex;
    flex-wrap: wrap;
    gap: 0.5rem;
    margin: 0.6rem 0 1rem;
}

/* Spaced CTA pills under a hero heading. */
.mkt-hero-links {
    display: flex;
    flex-wrap: wrap;
    gap: 0.5rem;
    margin-top: 0.5rem;
}

/* Vendor access — a distinct gold-accented panel with SQUARED buttons, deliberately unlike the round
   buyer pills so vendor sign-in / apply stand apart. */
.mkt-vendor-cta {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: 0.85rem;
    margin-top: 1rem;
    padding: 0.9rem 1rem;
    border: 1px solid var(--line);
    border-radius: 14px;
    background: var(--elevated);
}

.mkt-vendor-cta-copy {
    display: flex;
    flex-direction: column;
    gap: 0.15rem;
}

.mkt-vendor-cta-copy strong {
    font-size: 1rem;
}

.mkt-vendor-cta-copy span {
    font-size: 0.85rem;
    color: var(--muted);
}

.mkt-vendor-cta-inline {
    color: var(--brand-strong, #d4af37);
    font-weight: 600;
    white-space: nowrap;
}

.mkt-vendor-cta-actions {
    display: flex;
    flex-wrap: wrap;
    gap: 0.5rem;
}

.mkt-vendor-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border-radius: 10px;
    padding: 0.6rem 1rem;
    font-weight: 700;
    text-decoration: none;
    border: 1px solid var(--line);
    color: var(--ink);
    background: rgba(255, 255, 255, 0.03);
    transition: transform 150ms ease, box-shadow 150ms ease, border-color 150ms ease;
}

.mkt-vendor-btn-primary {
    background: var(--accent);
    border-color: var(--accent);
    color: #141414;
    font-weight: 800;
}
.mkt-vendor-btn-primary:hover {
    background: var(--accent-hover);
    border-color: var(--accent-hover);
}

.mkt-vendor-btn:hover,
.mkt-vendor-btn:focus-visible {
    transform: translateY(-1px);
    box-shadow: 0 6px 16px rgba(212, 175, 55, 0.25);
}

@media (max-width: 560px) {
    .mkt-vendor-cta-actions {
        width: 100%;
    }

    .mkt-vendor-btn {
        flex: 1;
    }
}

.mkt-search-hint {
    margin: 0.1rem 0 0;
    font-size: 0.76rem;
    color: var(--muted);
}

.mkt-deadend {
    margin-top: 0.5rem;
}

.mkt-wanted-list {
    max-height: 420px;
    overflow-y: auto;
}

/* Vendor reputation trust strip (objective signals, no star ratings). */
.mkt-trust {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 0.4rem 0.75rem;
    margin-top: 0.6rem;
}

.mkt-trust-badge {
    display: inline-flex;
    align-items: center;
    padding: 0.2rem 0.6rem;
    border-radius: 999px;
    background: rgba(212, 175, 55, 0.16);
    color: var(--accent);
    font-size: 0.78rem;
    font-weight: 700;
}

.mkt-trust-item {
    font-size: 0.8rem;
    color: var(--ink-secondary);
}

.mkt-offer-vendor {
    color: var(--accent);
    text-decoration: none;
    font-weight: 600;
}

.mkt-offer-vendor:hover {
    text-decoration: underline;
}

/* One-tap pricing helpers in the add-listing form (% of market, match/undercut lowest vendor). */
.mkt-price-helpers {
    display: flex;
    flex-direction: column;
    gap: 0.4rem;
    margin: 0.25rem 0 0.5rem;
}

.mkt-price-helper-row {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 0.35rem;
}

.mkt-price-helper-label {
    font-size: 0.8rem;
    color: var(--ink-secondary);
    margin-right: 0.25rem;
}

.mkt-pricing {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    margin: 0.25rem 0 0.5rem;
}

.mkt-checkbox {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    font-size: 0.85rem;
    color: var(--ink-secondary);
}

.mkt-checkbox input {
    width: auto;
}

.mkt-mode-select {
    max-width: 8.5rem;
}

/* Unified "sell your cards" form: intent picker + catalog picker + selected list. */
.sell-form .sell-step-label {
    display: block;
    font-weight: 600;
    margin-top: 0.6rem;
}

.sell-dest-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 0.6rem;
    margin: 0.25rem 0 0.5rem;
}
.sell-send-row {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: 6px;
    margin-top: 12px;
}
.sell-send-note { font-size: 0.85rem; }

.sell-dest {
    text-align: left;
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
    padding: 0.85rem;
    border: 1px solid var(--line);
    border-radius: 14px;
    background: transparent;
    color: inherit;
    cursor: pointer;
}

.sell-dest strong {
    font-size: 0.95rem;
}

.sell-dest span {
    font-size: 0.8rem;
    color: var(--ink-secondary);
}

.sell-dest-active {
    border-color: var(--accent);
    box-shadow: inset 0 0 0 1px var(--accent);
}

.sell-pick-grid {
    grid-template-columns: repeat(auto-fill, minmax(120px, 1fr));
}

.sell-selected {
    list-style: none;
    margin: 0.25rem 0;
    padding: 0;
    display: flex;
    flex-direction: column;
    gap: 0.4rem;
}

.sell-selected-item {
    display: flex;
    align-items: center;
    gap: 0.6rem;
    padding: 0.4rem 0.6rem;
    border: 1px solid var(--line);
    border-radius: 12px;
}

.sell-selected-thumb {
    border-radius: 4px;
    object-fit: cover;
}

.sell-selected-thumb-empty {
    width: 40px;
    height: 56px;
    background: rgba(0, 0, 0, 0.15);
    display: inline-block;
}

.sell-selected-info {
    display: flex;
    flex-direction: column;
    flex: 1;
    min-width: 0;
}

.sell-selected-info strong {
    font-size: 0.9rem;
}

.sell-selected-info .muted {
    font-size: 0.78rem;
}

/* Marketplace landing polish: value chips, idle prompt, how-it-works. */
.mkt-hero-chips {
    display: flex;
    flex-wrap: wrap;
    gap: 0.4rem;
    margin: 0.5rem 0;
}

.mkt-chip {
    font-size: 0.8rem;
    padding: 0.2rem 0.6rem;
    border-radius: 999px;
    border: 1px solid var(--line);
    color: var(--ink-secondary);
}

.mkt-idle {
    padding: 1rem 0;
    text-align: center;
}

.mkt-how-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 1rem;
    margin-top: 0.5rem;
}

.mkt-how-step {
    display: flex;
    flex-direction: column;
    gap: 0.3rem;
}

.mkt-how-num {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 1.8rem;
    height: 1.8rem;
    border-radius: 999px;
    background: color-mix(in srgb, var(--accent) 18%, transparent);
    color: var(--accent);
    font-weight: 700;
}

.mkt-how-step p {
    margin: 0;
    font-size: 0.9rem;
    color: var(--ink-secondary);
}

/* Vendor browse cards: name + location, an inventory preview strip, and trust signals. */
.mkt-vendor-grid {
    list-style: none;
    margin: 0;
    padding: 0;
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
    gap: 0.85rem;
}

.mkt-vendor-card {
    display: flex;
    flex-direction: column;
    gap: 0.6rem;
    padding: 0.9rem;
    border: 1px solid var(--line);
    border-radius: 16px;
    text-decoration: none;
    color: inherit;
    transition: border-color 0.15s ease;
}

.mkt-vendor-card:hover {
    border-color: color-mix(in srgb, var(--accent) 55%, transparent);
}

.mkt-vendor-card-top {
    display: flex;
    flex-direction: column;
    gap: 0.15rem;
}

.mkt-vendor-previews {
    display: flex;
    gap: 0.35rem;
    overflow: hidden;
}

.mkt-vendor-preview {
    width: 54px;
    height: 76px;
    object-fit: cover;
    border-radius: 6px;
    background: rgba(0, 0, 0, 0.15);
    flex: 0 0 auto;
}

.mkt-vendor-card-foot {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 0.4rem;
}

/* Non-English language flag on an offer — drawn so a Japanese/etc. card reads at a glance. */
.mkt-lang-badge {
    display: inline-block;
    margin-right: 0.4rem;
    padding: 0.02rem 0.4rem;
    border-radius: 999px;
    font-size: 0.72rem;
    font-weight: 600;
    border: 1px solid color-mix(in srgb, var(--accent) 45%, transparent);
    color: var(--accent);
}

/* "Mark sold" sits between Save and Delete; tint it so it reads as a positive close-out, not a destroy. */
.mkt-sold-btn {
    border-color: color-mix(in srgb, var(--accent) 45%, transparent);
    color: var(--accent);
}

/* Inbound contact requests (the lead funnel). */
.mkt-request-message {
    font-style: italic;
    color: var(--ink-secondary);
}

.mkt-request-badge {
    display: inline-block;
    margin-left: 0.5rem;
    padding: 0.05rem 0.45rem;
    border-radius: 999px;
    font-size: 0.7rem;
    font-weight: 600;
    vertical-align: middle;
    border: 1px solid var(--line);
    color: var(--ink-secondary);
}

.mkt-request-badge-new {
    border-color: color-mix(in srgb, var(--accent) 55%, transparent);
    color: var(--accent);
}

.mkt-request-badge-sold {
    border-color: color-mix(in srgb, var(--accent) 45%, transparent);
    color: var(--accent);
}

.mkt-request-history {
    margin-top: 1rem;
}

/* Compact one-line filter bar: search grows, game + type are dropdowns (not pill walls). */
.mkt-filter-row {
    display: flex;
    flex-wrap: wrap;
    gap: 0.75rem;
    align-items: flex-end;
    margin-bottom: 0.5rem;
}

.mkt-filter-search {
    flex: 1 1 240px;
    min-width: 0;
}

.mkt-filter-field {
    flex: 0 1 170px;
    min-width: 130px;
}

.mkt-filter-search .lf-search-input,
.mkt-filter-field .lf-set-select {
    width: 100%;
}

.mkt-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
    gap: 1rem;
    margin-top: 1rem;
}

/* --- First-class user profiles: avatar, badges, profile header --- */
.user-avatar {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border-radius: 50%;
    overflow: hidden;
    background: linear-gradient(135deg, #3a3a3a, #1e1e1e);
    color: var(--ink);
    font-weight: 700;
    flex-shrink: 0;
    border: 1px solid rgba(255, 255, 255, 0.12);
}
.user-avatar img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}
.user-avatar-lg {
    width: 88px;
    height: 88px;
    font-size: 2rem;
}
.user-avatar-sm {
    width: 32px;
    height: 32px;
    font-size: 0.9rem;
}
.user-profile-head {
    display: flex;
    align-items: center;
    gap: 1rem;
    flex-wrap: wrap;
}
.user-profile-dps { display: inline-flex; align-items: center; gap: 5px; margin-top: 6px; padding: 4px 11px; border-radius: 999px;
    font-size: 0.82rem; font-weight: 700; color: #ff9a6a; background: rgba(255,90,60,0.12); border: 1px solid rgba(255,90,60,0.35); }
.user-profile-dps strong { color: #ffd0b0; font-size: 0.9rem; }
.user-profile-meta h1 {
    margin: 0 0 0.15rem;
}
.user-badges {
    display: flex;
    flex-wrap: wrap;
    gap: 0.35rem;
    margin-top: 0.35rem;
}
.user-badge {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    font-size: 0.85rem;
    font-weight: 700;
    letter-spacing: 0.02em;
    color: #fff;
    padding: 0.24rem 0.62rem;
    border-radius: 999px;
    text-shadow: 0 1px 1px rgba(0, 0, 0, 0.35);
    white-space: nowrap;
    appearance: none;
    border: none;
    cursor: pointer;
    font-family: inherit;
}
.user-badge:hover { filter: brightness(1.08); }
.user-badge-icon {
    font-size: 1.5em; /* scales with the pill; BadgeArt renders relative to this so the art reads big */
    line-height: 0;
}

/* Level-up celebration overlay (confetti + pop-in card). Fires once per level. */
.levelup-overlay {
    position: fixed;
    inset: 0;
    z-index: 5000;
    display: flex;
    align-items: center;
    justify-content: center;
    background: rgba(0, 0, 0, 0.4);
    animation: levelup-fade 0.3s ease;
    cursor: pointer;
}
.levelup-confetti {
    position: absolute;
    inset: 0;
    overflow: hidden;
    pointer-events: none;
}
.levelup-confetti > span {
    position: absolute;
    top: 0;
    width: 10px;
    height: 14px;
    border-radius: 2px;
    opacity: 0.95;
    animation-name: levelup-fall;
    animation-timing-function: ease-in;
    animation-iteration-count: 1;
    animation-fill-mode: forwards;
}
.levelup-card {
    position: relative;
    text-align: center;
    max-width: 320px;
    background: linear-gradient(160deg, #241a08, #171717);
    border: 1px solid rgba(255, 215, 94, 0.5);
    border-radius: 22px;
    padding: 2rem 2.4rem;
    box-shadow: 0 0 70px rgba(255, 215, 94, 0.35);
    animation: levelup-pop 0.55s cubic-bezier(0.2, 1.4, 0.4, 1);
}
.levelup-emoji {
    font-size: 2.8rem;
    line-height: 1;
    animation: levelup-bob 1.4s ease-in-out infinite;
}
.levelup-title {
    margin-top: 0.4rem;
    font-size: 1.65rem;
    font-weight: 900;
    letter-spacing: 0.08em;
    color: #ffd75e;
    text-shadow: 0 2px 14px rgba(255, 215, 94, 0.55);
}
.levelup-badge {
    display: inline-block;
    margin: 0.55rem 0;
    font-size: 1.15rem;
    font-weight: 800;
    color: #1a1400;
    background: linear-gradient(135deg, #ffd75e, #c8a24a);
    border-radius: 999px;
    padding: 0.28rem 1rem;
}
.levelup-sub {
    font-size: 0.82rem;
    color: rgba(255, 255, 255, 0.72);
}
@keyframes levelup-fall {
    0% { transform: translateY(-24px) rotate(0deg); opacity: 1; }
    100% { transform: translateY(108vh) rotate(720deg); opacity: 0.85; }
}
@keyframes levelup-pop {
    0% { transform: scale(0.6); opacity: 0; }
    100% { transform: scale(1); opacity: 1; }
}
@keyframes levelup-bob {
    0%, 100% { transform: translateY(0); }
    50% { transform: translateY(-6px); }
}
@keyframes levelup-fade {
    from { opacity: 0; }
    to { opacity: 1; }
}
/* Milestone (every 5th level): prismatic gradient border + pulsing glow + bigger confetti. */
.levelup-card.is-milestone {
    border: 2px solid transparent;
    border-radius: 24px;
    background:
        linear-gradient(160deg, #1a0f2e, #171717) padding-box,
        linear-gradient(120deg, #ff4d4d, #ffd75e, #4ade80, #38bdf8, #c084fc) border-box;
    box-shadow: 0 0 90px rgba(192, 132, 252, 0.45);
    animation: levelup-pop 0.6s cubic-bezier(0.2, 1.4, 0.4, 1), levelup-glow 2.4s ease-in-out infinite;
}
.levelup-ribbon {
    display: inline-block;
    margin-bottom: 0.5rem;
    font-size: 0.68rem;
    font-weight: 900;
    letter-spacing: 0.18em;
    color: #1a1400;
    background: linear-gradient(90deg, #ffd75e, #ff9f1c);
    padding: 0.16rem 0.7rem;
    border-radius: 999px;
}
.levelup-card.is-milestone .levelup-title {
    background: linear-gradient(90deg, #ff9f1c, #ffd75e, #4ade80, #38bdf8, #c084fc);
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
    text-shadow: none;
}
.levelup-confetti.is-milestone > span {
    width: 12px;
    height: 17px;
}
@keyframes levelup-glow {
    0%, 100% { box-shadow: 0 0 70px rgba(192, 132, 252, 0.35); }
    50% { box-shadow: 0 0 115px rgba(56, 189, 248, 0.55); }
}

/* XP level badge + progress-to-next bar. */
.user-level {
    margin-top: 0.5rem;
    max-width: 320px;
}
.user-level-row {
    display: flex;
    align-items: baseline;
    gap: 0.5rem;
    margin-bottom: 0.25rem;
}
.user-level-badge {
    display: inline-block;
    font-size: 0.72rem;
    font-weight: 800;
    letter-spacing: 0.03em;
    color: #1a1400;
    background: linear-gradient(135deg, #ffd75e, #c8a24a);
    border-radius: 999px;
    padding: 0.1rem 0.5rem;
}
.user-level-xp {
    font-size: 0.75rem;
}
.user-level-bar {
    height: 9px;
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.1);
    overflow: hidden;
}
.user-level-bar > span {
    position: relative;
    display: block;
    height: 100%;
    border-radius: 999px;
    background: linear-gradient(90deg, #c8a24a, #ffd75e);
    box-shadow: 0 0 10px rgba(255, 215, 94, 0.45);
    overflow: hidden;
    /* The sweep on load — a slow, satisfying fill from 0 to target. */
    transition: width 1.1s cubic-bezier(0.22, 1, 0.36, 1) 0.15s;
}
/* A highlight that slides across the fill, so the bar reads as "live" not static. */
.user-level-shine {
    position: absolute;
    inset: 0;
    background: linear-gradient(100deg, transparent 20%, rgba(255, 255, 255, 0.55) 50%, transparent 80%);
    transform: translateX(-100%);
    animation: level-shine 2.6s ease-in-out 1.2s infinite;
}
@keyframes level-shine {
    0% { transform: translateX(-100%); }
    60%, 100% { transform: translateX(100%); }
}

/* ===== Rewards hub (profile) ===== */
.rewards-hub-card {
    background:
        radial-gradient(120% 140% at 100% 0%, rgba(255, 215, 94, 0.14), transparent 55%),
        linear-gradient(160deg, rgba(30, 24, 48, 0.6), rgba(20, 20, 31, 0.4));
    border: 1px solid rgba(255, 215, 94, 0.22);
}
.rewards-hero {
    display: flex;
    flex-direction: column;
    gap: 16px;
}
.rewards-hero-id {
    display: flex;
    align-items: center;
    gap: 16px;
}
/* Avatar wrapped in a conic-gradient ring that fills with the member's progress to next level. */
.level-ring {
    position: relative;
    flex: 0 0 auto;
    width: 92px;
    height: 92px;
    border-radius: 50%;
    padding: 5px;
    background:
        conic-gradient(#ffd75e var(--ring-pct, 0%), rgba(255, 255, 255, 0.12) 0);
    box-shadow: 0 0 18px rgba(255, 215, 94, 0.3);
}
/* Tap the avatar to edit it — the display itself is the call to action. */
.level-ring.is-editable {
    display: block;
    cursor: pointer;
    text-decoration: none;
    transition: transform 0.15s ease, box-shadow 0.15s ease;
}
.level-ring.is-editable:hover,
.level-ring.is-editable:focus-visible {
    transform: scale(1.04);
    box-shadow: 0 0 22px rgba(255, 215, 94, 0.55);
    outline: none;
}
.level-ring-edit {
    position: absolute;
    z-index: 4;
    top: -2px;
    right: -2px;
    width: 26px;
    height: 26px;
    border-radius: 50%;
    display: grid;
    place-items: center;
    font-size: 0.8rem;
    background: linear-gradient(90deg, #c8a24a, #ffd75e);
    color: #171008;
    border: 2px solid #14141f;
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.45);
}
.level-ring.is-editable:hover .level-ring-edit {
    transform: scale(1.08);
}
.level-ring .user-avatar-xl {
    width: 100%;
    height: 100%;
    border-radius: 50%;
    overflow: hidden;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #14141f;
    border: 3px solid #14141f;
    font-size: 2rem;
    font-weight: 800;
    color: #ffd75e;
}
.level-ring .user-avatar-xl img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}
.level-ring-badge {
    position: absolute;
    z-index: 3;
    bottom: -4px;
    left: 50%;
    transform: translateX(-50%);
    background: linear-gradient(90deg, #c8a24a, #ffd75e);
    color: #171008;
    font-weight: 800;
    font-size: 0.72rem;
    padding: 2px 10px;
    border-radius: 999px;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.4);
    white-space: nowrap;
}
.rewards-hero-meta {
    display: flex;
    flex-direction: column;
    gap: 6px;
    min-width: 0;
}
.rank-chip {
    align-self: flex-start;
    display: inline-flex;
    align-items: center;
    gap: 6px;
    background: rgba(255, 215, 94, 0.14);
    border: 1px solid rgba(255, 215, 94, 0.35);
    color: #ffd75e;
    font-weight: 700;
    font-size: 0.85rem;
    padding: 3px 12px;
    border-radius: 999px;
}
.rewards-hero-name {
    font-size: 1.35rem;
    font-weight: 800;
    line-height: 1.1;
}
.rewards-hero-next {
    font-size: 0.92rem;
    padding: 10px 14px;
    border-radius: 12px;
    background: rgba(255, 255, 255, 0.04);
    border: 1px dashed rgba(255, 215, 94, 0.3);
}
.rewards-hero-next strong {
    color: #ffd75e;
}
.rewards-hero-actions {
    display: flex;
    flex-wrap: wrap;
    gap: 10px;
}
.rewards-preview-btn {
    appearance: none;
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    font: inherit;
    font-weight: 700;
    font-size: 0.9rem;
    padding: 9px 16px;
    border-radius: 999px;
    /* Force dark text + no underline so global <a> link styles can't make it an unreadable blue link. */
    color: #171008 !important;
    text-decoration: none !important;
    background: linear-gradient(90deg, #c8a24a, #ffd75e);
    border: 1px solid transparent;
    transition: transform 120ms ease, box-shadow 120ms ease;
}
.rewards-preview-btn:hover {
    transform: translateY(-1px);
    box-shadow: 0 6px 18px rgba(255, 215, 94, 0.3);
}
.rewards-preview-btn.is-ghost {
    color: #ffd75e;
    background: transparent;
    border-color: rgba(255, 215, 94, 0.4);
}

/* Quick-action tiles — "Your stuff". Real tiles, not flat gray rows. */
.hub-tiles {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
    gap: 12px;
}
.hub-tile {
    display: flex;
    flex-direction: column;
    gap: 3px;
    padding: 16px 14px;
    border-radius: 14px;
    text-decoration: none;
    color: var(--ink);
    background: rgba(255, 255, 255, 0.03);
    border: 1px solid var(--border, rgba(255, 255, 255, 0.08));
    transition: border-color 140ms ease, transform 140ms ease, background 140ms ease;
}
.hub-tile:hover {
    transform: translateY(-2px);
    border-color: rgba(255, 215, 94, 0.45);
    background: rgba(255, 215, 94, 0.06);
}
.hub-tile-icon {
    font-size: 1.6rem;
}
.hub-tile-label {
    font-weight: 700;
}
.hub-tile-sub {
    font-size: 0.8rem;
}

/* Collapsible account settings — keeps the boring form out of the way of the fun stuff. */
.hub-account > summary {
    cursor: pointer;
    display: flex;
    flex-wrap: wrap;
    align-items: baseline;
    gap: 8px 12px;
    list-style: none;
}
.hub-account > summary::-webkit-details-marker { display: none; }
.hub-account > summary::before {
    content: "▸";
    color: #ffd75e;
    transition: transform 150ms ease;
    display: inline-block;
}
.hub-account[open] > summary::before { transform: rotate(90deg); }
.hub-account-summary {
    font-weight: 700;
    font-size: 1.05rem;
}

/* Collapsible profile-hub sections — the long customizers (border/background/frame/badges/etc.) start closed
   so the hub stays scannable; tap a header to expand. Reuses the account-details disclosure look. */
.hub-collapse > summary {
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: 10px;
    list-style: none;
}
.hub-collapse > summary::-webkit-details-marker { display: none; }
.hub-collapse > summary::before {
    content: "▸";
    color: #ffd75e;
    font-size: 0.9em;
    transition: transform 150ms ease;
    display: inline-block;
    flex: 0 0 auto;
}
.hub-collapse[open] > summary::before { transform: rotate(90deg); }
.hub-collapse > summary h2 { margin: 0; }
.hub-collapse > summary::after {
    content: "Tap to expand";
    margin-left: auto;
    color: var(--muted, #9aa7b5);
    font-size: 0.72rem;
    font-weight: 600;
    white-space: nowrap;
}
.hub-collapse[open] > summary::after { content: "Tap to collapse"; }
.hub-collapse[open] > summary { margin-bottom: 1rem; }

/* ===== Rewards track (roadmap) ===== */
.track-topbar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
}
.track-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    margin-bottom: 10px;
}
.track-head-level {
    font-weight: 800;
    font-size: 1.1rem;
    color: #ffd75e;
}
.track-head-count {
    margin-top: 10px;
    font-size: 0.9rem;
    font-weight: 600;
}

.track-spine {
    list-style: none;
    margin: 12px 0 0;
    padding: 0;
}
.track-node {
    position: relative;
    display: flex;
    gap: 14px;
    padding-bottom: 20px;
}
/* Connector line behind the markers. Gold up to what's reached, dim beyond. */
.track-node:not(:last-child)::before {
    content: "";
    position: absolute;
    left: 17px;
    top: 36px;
    bottom: -2px;
    width: 2px;
    background: rgba(255, 255, 255, 0.12);
}
.track-node.is-done:not(:last-child)::before {
    background: linear-gradient(#ffd75e, #c8a24a);
}
.track-node-marker {
    flex: 0 0 auto;
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 800;
    font-size: 0.9rem;
    background: rgba(255, 255, 255, 0.06);
    border: 2px solid rgba(255, 255, 255, 0.16);
    color: var(--ink);
    z-index: 1;
}
.track-node.is-done .track-node-marker {
    background: linear-gradient(135deg, #c8a24a, #ffd75e);
    border-color: transparent;
    color: #171008;
}
.track-node.is-next .track-node-marker {
    border-color: #ffd75e;
    color: #ffd75e;
    animation: track-next-pulse 1.8s ease-in-out infinite;
}
@keyframes track-next-pulse {
    0%, 100% { box-shadow: 0 0 0 0 rgba(255, 215, 94, 0.5); }
    50% { box-shadow: 0 0 0 7px rgba(255, 215, 94, 0); }
}
.track-node-body { flex: 1 1 auto; min-width: 0; padding-top: 4px; }
.track-node-head {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 8px;
    margin-bottom: 6px;
}
.track-node-level { font-weight: 700; }
.track-next-tag {
    font-size: 0.72rem;
    font-weight: 800;
    letter-spacing: 0.03em;
    color: #171008;
    background: linear-gradient(90deg, #c8a24a, #ffd75e);
    padding: 2px 9px;
    border-radius: 999px;
}
.track-done-tag {
    font-size: 0.72rem;
    font-weight: 700;
    color: #9de5a9;
}
.track-node.is-next .track-node-body {
    /* Make the next step pop. */
    background: rgba(255, 215, 94, 0.06);
    border: 1px solid rgba(255, 215, 94, 0.3);
    border-radius: 12px;
    padding: 8px 12px;
    margin-top: -4px;
}
.track-unlocks {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
}
.track-unlock {
    font-size: 0.82rem;
    padding: 3px 10px;
    border-radius: 999px;
    border: 1px solid rgba(255, 255, 255, 0.14);
    background: rgba(255, 255, 255, 0.03);
}
.track-unlock.is-rank {
    border-color: rgba(255, 215, 94, 0.4);
    background: rgba(255, 215, 94, 0.08);
}
.track-unlock.is-badge { border-width: 1px; border-style: solid; }
.track-unlock.is-perk {
    border-style: dashed;
    color: var(--muted, #b9b4c8);
}
.track-soon {
    font-style: normal;
    font-size: 0.72rem;
    opacity: 0.7;
}
.track-node:not(.is-done) .track-unlock:not(.is-rank) { opacity: 0.82; }

/* Achievements grid */
.track-ach-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
    gap: 12px;
    margin-top: 12px;
}
.track-ach {
    padding: 14px;
    border-radius: 14px;
    border: 1px solid var(--border, rgba(255, 255, 255, 0.08));
    background: rgba(255, 255, 255, 0.03);
}
.track-ach.is-done {
    border-color: color-mix(in srgb, #4caf50 45%, transparent);
    background: color-mix(in srgb, #4caf50 8%, transparent);
}
.track-ach-top {
    display: flex;
    align-items: center;
    gap: 8px;
    margin-bottom: 4px;
}
.track-ach-icon { font-size: 1.9rem; line-height: 0; }
.track-ach-label { font-weight: 700; flex: 1 1 auto; }
.track-ach-check {
    font-size: 0.7rem;
    font-weight: 700;
    color: #4caf50;
}
.track-ach-desc { font-size: 0.8rem; margin-bottom: 8px; }
.track-ach-bar {
    height: 8px;
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.1);
    overflow: hidden;
}
.track-ach-bar > span {
    display: block;
    height: 100%;
    border-radius: 999px;
    width: var(--pct, 0%);
    background: linear-gradient(90deg, #c8a24a, #ffd75e);
    animation: track-fill 1s cubic-bezier(0.22, 1, 0.36, 1) 0.1s both;
}
.track-ach.is-done .track-ach-bar > span {
    background: linear-gradient(90deg, #3f9b52, #6fd67f);
}
@keyframes track-fill {
    from { width: 0; }
    to { width: var(--pct, 0%); }
}
.track-ach-progress { font-size: 0.78rem; margin-top: 6px; font-weight: 600; }

/* ===== Custom profile borders (cosmetic avatar frames) ===== */
/* Box-shadow rings/glows so every frame renders on ANY avatar without being clipped by its overflow. */
.av-border { position: relative; }

/* --- Static solids & glows --- */
.av-border-bronze { box-shadow: 0 0 0 3px #a9713b, 0 0 8px rgba(169, 113, 59, 0.5); }
.av-border-aqua { box-shadow: 0 0 0 3px #35c9d6, 0 0 13px rgba(53, 201, 214, 0.7); }
.av-border-silver { box-shadow: 0 0 0 3px #c9ccd4, 0 0 8px rgba(201, 204, 212, 0.55); }
.av-border-crimson { box-shadow: 0 0 0 3px #e23b4e, 0 0 13px rgba(226, 59, 78, 0.7); }
.av-border-emerald { box-shadow: 0 0 0 3px #2fae72, 0 0 12px rgba(47, 174, 114, 0.62); }
.av-border-sky { box-shadow: 0 0 0 3px #4a90ff, 0 0 13px rgba(74, 144, 255, 0.7); }
.av-border-rose { box-shadow: 0 0 0 3px #ff5fa2, 0 0 13px rgba(255, 95, 162, 0.7); }
.av-border-gold { box-shadow: 0 0 0 3px #ffd75e, 0 0 15px rgba(255, 215, 94, 0.72); }

/* --- Animated glows & color cycles --- */
.av-border-ember { animation: av-ember 1.8s ease-in-out infinite; }
.av-border-neon { animation: av-neon 1.3s ease-in-out infinite; }
.av-border-sunset { animation: av-sunset 4s linear infinite; }
.av-border-ocean { animation: av-ocean 4s linear infinite; }
.av-border-aurora { animation: av-aurora 6s linear infinite; }
.av-border-amethyst { animation: av-amethyst 2.2s ease-in-out infinite; }
.av-border-frost { animation: av-frost 3s ease-in-out infinite; }
.av-border-inferno { animation: av-inferno 0.85s ease-in-out infinite; }
.av-border-rainbow { animation: av-rainbow 3s linear infinite; }
.av-border-cosmic { animation: av-cosmic 5s linear infinite; }
.av-border-legendary { animation: av-legendary 4s linear infinite; }
/* Activity-earned cosmetic borders (farming meta expansion) */
.av-border-sailor { box-shadow: 0 0 0 3px #4aa3d4, 0 0 14px rgba(74, 163, 212, 0.7); }
.av-border-warborn { box-shadow: 0 0 0 3px #e0687a, 0 0 14px rgba(224, 104, 122, 0.72); }
.av-border-artisan { box-shadow: 0 0 0 3px #c9a2ff, 0 0 13px rgba(201, 162, 255, 0.7); }
.av-border-kindred { box-shadow: 0 0 0 3px #ffb14a, 0 0 13px rgba(255, 177, 74, 0.68); }
.av-border-harvest_crown { animation: av-harvest 4s ease-in-out infinite; }
@keyframes av-harvest { 0%, 100% { box-shadow: 0 0 0 3px #ffcf5e, 0 0 10px rgba(255, 207, 94, 0.6); } 50% { box-shadow: 0 0 0 3px #ffe27a, 0 0 20px rgba(255, 207, 94, 0.95); } }

@keyframes av-ember {
    0%, 100% { box-shadow: 0 0 0 3px #ff7a1a, 0 0 8px rgba(255, 122, 26, 0.5); }
    50% { box-shadow: 0 0 0 3px #ff9d3d, 0 0 20px rgba(255, 122, 26, 0.95); }
}
@keyframes av-neon {
    0%, 100% { box-shadow: 0 0 0 3px #39ff88, 0 0 8px rgba(57, 255, 136, 0.5); }
    50% { box-shadow: 0 0 0 3px #39ff88, 0 0 24px rgba(57, 255, 136, 1); }
}
@keyframes av-sunset {
    0%, 100% { box-shadow: 0 0 0 3px #ff9d3d, 0 0 14px rgba(255, 157, 61, 0.75); }
    50% { box-shadow: 0 0 0 3px #ff4d8d, 0 0 16px rgba(255, 77, 141, 0.8); }
}
@keyframes av-ocean {
    0%, 100% { box-shadow: 0 0 0 3px #2a6db0, 0 0 14px rgba(42, 109, 176, 0.75); }
    50% { box-shadow: 0 0 0 3px #35c9d6, 0 0 18px rgba(53, 201, 214, 0.85); }
}
@keyframes av-aurora {
    0% { box-shadow: 0 0 0 3px #4ade80, 0 0 16px rgba(74, 222, 128, 0.75); }
    33% { box-shadow: 0 0 0 3px #35c9d6, 0 0 16px rgba(53, 201, 214, 0.75); }
    66% { box-shadow: 0 0 0 3px #a06cff, 0 0 16px rgba(160, 108, 255, 0.75); }
    100% { box-shadow: 0 0 0 3px #4ade80, 0 0 16px rgba(74, 222, 128, 0.75); }
}
@keyframes av-amethyst {
    0%, 100% { box-shadow: 0 0 0 3px #a06cff, 0 0 6px rgba(160, 108, 255, 0.4); }
    50% { box-shadow: 0 0 0 3px #bb92ff, 0 0 20px rgba(160, 108, 255, 0.9); }
}
@keyframes av-frost {
    0%, 100% { box-shadow: 0 0 0 3px #bfe9ff, 0 0 10px rgba(191, 233, 255, 0.6); }
    50% { box-shadow: 0 0 0 3px #7fd4ff, 0 0 22px rgba(127, 212, 255, 0.95); }
}
@keyframes av-inferno {
    0%, 100% { box-shadow: 0 0 0 3px #ff3d2e, 0 0 12px rgba(255, 61, 46, 0.75); }
    50% { box-shadow: 0 0 0 3px #ffae2e, 0 0 24px rgba(255, 90, 20, 1); }
}
@keyframes av-rainbow {
    0% { box-shadow: 0 0 0 3px #ff4d4d, 0 0 15px rgba(255, 77, 77, 0.75); }
    20% { box-shadow: 0 0 0 3px #ff9f1c, 0 0 15px rgba(255, 159, 28, 0.75); }
    40% { box-shadow: 0 0 0 3px #4ade80, 0 0 15px rgba(74, 222, 128, 0.75); }
    60% { box-shadow: 0 0 0 3px #38bdf8, 0 0 15px rgba(56, 189, 248, 0.75); }
    80% { box-shadow: 0 0 0 3px #c084fc, 0 0 15px rgba(192, 132, 252, 0.75); }
    100% { box-shadow: 0 0 0 3px #ff4d4d, 0 0 15px rgba(255, 77, 77, 0.75); }
}
@keyframes av-cosmic {
    0%, 100% { box-shadow: 0 0 0 3px #7b5cff, 0 0 18px rgba(123, 92, 255, 0.8); }
    50% { box-shadow: 0 0 0 3px #ff5fd0, 0 0 18px rgba(255, 95, 208, 0.8); }
}
@keyframes av-legendary {
    0% { box-shadow: 0 0 0 3px #ff4d4d, 0 0 16px rgba(255, 77, 77, 0.7); }
    25% { box-shadow: 0 0 0 3px #ffd75e, 0 0 16px rgba(255, 215, 94, 0.7); }
    50% { box-shadow: 0 0 0 3px #4ade80, 0 0 16px rgba(74, 222, 128, 0.7); }
    75% { box-shadow: 0 0 0 3px #38bdf8, 0 0 16px rgba(56, 189, 248, 0.7); }
    100% { box-shadow: 0 0 0 3px #c084fc, 0 0 16px rgba(192, 132, 252, 0.7); }
}
/* --- Role-exclusive (badge-gated) frames --- */
.av-border-role_admin { animation: av-role-admin 3s linear infinite; }
.av-border-role_dev { animation: av-role-dev 1.6s ease-in-out infinite; }
.av-border-role_staff { animation: av-role-staff 3.2s linear infinite; }
.av-border-role_volunteer { animation: av-role-volunteer 2.4s ease-in-out infinite; }
@keyframes av-role-admin {
    0%, 100% { box-shadow: 0 0 0 3px #3b82f6, 0 0 16px rgba(59, 130, 246, 0.85); }
    50% { box-shadow: 0 0 0 3px #ffd75e, 0 0 16px rgba(255, 215, 94, 0.85); }
}
@keyframes av-role-dev {
    0%, 100% { box-shadow: 0 0 0 3px #22c55e, 0 0 10px rgba(34, 197, 94, 0.6); }
    50% { box-shadow: 0 0 0 3px #4ade80, 0 0 22px rgba(34, 197, 94, 1); }
}
@keyframes av-role-staff {
    0%, 100% { box-shadow: 0 0 0 3px #ffd75e, 0 0 16px rgba(255, 215, 94, 0.85); }
    50% { box-shadow: 0 0 0 3px #a06cff, 0 0 16px rgba(160, 108, 255, 0.85); }
}
@keyframes av-role-volunteer {
    0%, 100% { box-shadow: 0 0 0 3px #2dd4bf, 0 0 10px rgba(45, 212, 191, 0.6); }
    50% { box-shadow: 0 0 0 3px #5eead4, 0 0 20px rgba(45, 212, 191, 0.95); }
}

