    position: absolute;
    top: -2px;
    right: -2px;
    min-width: 20px;
    height: 20px;
    padding: 0 5px;
    border-radius: 10px;
    background: #e5484d;
    color: #fff;
    font-size: 0.72rem;
    font-weight: 700;
    display: flex;
    align-items: center;
    justify-content: center;
    border: 2px solid var(--bg, #0e0e12);
}
.mkt-dock-panel {
    position: fixed;
    right: 20px;
    bottom: 86px;
    z-index: 900;
    width: min(370px, calc(100vw - 32px));
    height: min(560px, calc(100vh - 130px));
