    text-overflow: ellipsis;
    white-space: nowrap;
}
.mkt-dock-tag {
    font-size: 0.68rem;
    padding: 1px 6px;
    border-radius: 6px;
    background: color-mix(in srgb, var(--accent) 16%, transparent);
    color: var(--accent);
    flex: 0 0 auto;
}
.mkt-dock-preview {
    font-size: 0.82rem;
    color: var(--muted, #b9b4c7);
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}
.mkt-dock-msgs {
    overflow-y: auto;
    flex: 1;
    min-height: 0;
    padding: 12px;
    display: flex;
    flex-direction: column;
    gap: 6px;
}
.mkt-dock-empty {
    padding: 16px;
    text-align: center;
}
.mkt-dock-bubble {
    max-width: 80%;
    padding: 8px 11px;
    border-radius: 13px;
