/* --- Community / friends directory (tile grid) --- */
.mkt-social-hero h1 {
    margin-bottom: 4px;
}
.mkt-member-filter {
    width: 100%;
    margin-top: 12px;
}
.mkt-social-h2 {
    display: flex;
    align-items: center;
    gap: 8px;
    margin: 0 0 12px;
}
.mkt-count-pill {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 22px;
    height: 22px;
    padding: 0 7px;
    border-radius: 11px;
    background: color-mix(in srgb, var(--accent) 20%, transparent);
    color: var(--accent);
    font-size: 0.8rem;
    font-weight: 700;
}
.mkt-member-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(158px, 1fr));
