.pet-card.rarity-ascendant { border-color: rgba(255,122,60,0.4); }
.pet-card.rarity-eternal { border-color: rgba(255,92,200,0.4); }
.pet-buffs { display: flex; flex-direction: column; gap: 2px; font-size: 0.72rem; color: #cbd2da; }
.pet-perk { color: #ffd75e; font-weight: 700; }
.pet-card-btn { cursor: pointer; font: inherit; color: inherit; width: 100%; }
.pet-card-btn:hover { transform: translateY(-2px); border-color: rgba(255,215,94,0.5); }
.pet-status-owned { font-size: 0.72rem; font-weight: 700; color: #7ad07a; margin-top: 2px; }

/* Pet detail modal */
.petx-detail { max-width: 400px; }

/* Pet detail rendered as a full in-flow PAGE (breadcrumb back) instead of a modal — scrolls normally,
   so tall content (level tiers + abilities + the give-a-copy member search) is always reachable. */
.petx-page { display: flex; flex-direction: column; gap: 12px; }
.petx-crumb { align-self: flex-start; background: none; border: none; color: #9aa0a6; font-weight: 800; font-size: 0.95rem; cursor: pointer; padding: 4px 2px; }
.petx-crumb:hover { color: #ffd75e; }
.petx-detail-card { position: relative; width: 100%; max-width: 560px; margin: 0 auto; background: linear-gradient(180deg, #1b1e26, #12141a); border: 1px solid #2a2f37; border-radius: 20px; padding: 22px 20px 20px; text-align: center; }
.petx-detail-card.rarity-common { --glow: #9aa0a6; }
.petx-detail-card.rarity-rare { --glow: #4aa3ff; }
.petx-detail-card.rarity-epic { --glow: #b76bff; }
.petx-detail-card.rarity-legendary { --glow: #ffb020; }
.petx-detail-card.rarity-mythic { --glow: #33e0a1; }
.petx-detail-card.rarity-ascendant { --glow: #ff7a3c; }
.petx-detail-card.rarity-eternal { --glow: #ff5cc8; }
.petx-detail-card { border-color: color-mix(in srgb, var(--glow, #2a2f37) 45%, #2a2f37); box-shadow: 0 0 30px -12px var(--glow, transparent), 0 20px 50px rgba(0,0,0,0.4); }
/* Give-a-copy panel folded into the detail page: warning + member search → hero-card results. */
.petx-give { margin-top: 14px; padding-top: 14px; border-top: 1px solid rgba(255,255,255,0.08); text-align: left; }
.petx-give-results { display: flex; flex-direction: column; gap: 8px; margin-top: 10px; max-height: 60vh; overflow-y: auto; }
.btn-ghost.is-active { border-color: #ffd75e; color: #ffd75e; }
.petx-abilities { text-align: left; display: flex; flex-direction: column; gap: 10px; margin: 14px 0 10px; }
/* Each ability gets its OWN accent (passive=teal, rarity=violet, signature=gold, real-world=green) and a left
   accent bar, so the four blocks read as different KINDS of thing instead of four identical dark boxes. */
.petx-ability { position: relative; background: rgba(255,255,255,0.04); border: 1px solid #2a2f37; border-radius: 12px; padding: 10px 12px 11px 14px; overflow: hidden; }
.petx-ability::before { content: ""; position: absolute; left: 0; top: 0; bottom: 0; width: 3px; background: var(--petx-accent, #6b7686); }
.petx-ability-head { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; margin-bottom: 6px; }
/* The label is a chip now — the old full-width ALL-CAPS sentence shouted and wrapped to two lines on a phone. */
.petx-tag { font-size: 0.66rem; font-weight: 900; text-transform: uppercase; letter-spacing: 0.05em; color: var(--petx-accent, #cbd2da); background: rgba(255,255,255,0.07); border: 1px solid rgba(255,255,255,0.15); border-radius: 999px; padding: 2.5px 8px; white-space: nowrap; }
.petx-ability-note { font-size: 0.7rem; color: #8b93a0; font-weight: 600; }
.petx-ability-body { font-size: 0.84rem; color: #e7dcc4; line-height: 1.4; }

/* The dopamine line: the number is the point, so it gets to be big. */
.petx-statline { display: flex; align-items: baseline; gap: 7px; flex-wrap: wrap; margin: 2px 0 5px; }
.petx-statbig { font-size: 1.6rem; font-weight: 900; line-height: 1; color: var(--petx-accent, #ffd75e); text-shadow: 0 0 16px rgba(255,255,255,0.16); }
.petx-statname { font-size: 0.9rem; font-weight: 800; color: #e7dcc4; }
.petx-statnext { font-size: 0.72rem; font-weight: 700; color: #7ad07a; background: rgba(122,208,122,0.12); border-radius: 999px; padding: 2px 7px; }
.petx-perkname { font-size: 0.98rem; font-weight: 900; color: #ffe9a8; margin: 1px 0 4px; }

.petx-passive { --petx-accent: #4fc3d9; }
.petx-active { --petx-accent: #ffd75e; }
.petx-active.is-live { background: rgba(255,215,94,0.09); border-color: rgba(255,215,94,0.34); }
.petx-pending { color: #e0a83c; font-weight: 700; }
.petx-status { margin-bottom: 12px; font-size: 0.82rem; }
.petx-owned { color: #7ad07a; font-weight: 800; }
.petx-lockrow { color: #9a93a6; font-weight: 700; }
/* Green, not gold — gold now means the equipped signature buff, and two gold cards read as the same thing. */
.petx-realworld { --petx-accent: #7ad07a; background: rgba(122,208,122,0.09); border-color: rgba(122,208,122,0.32); }
.pet-locked { font-size: 0.74rem; color: #9a93a6; margin-top: 2px; }
.pet-btn { margin-top: 4px; padding: 6px 12px; font-size: 0.8rem; }
.pet-featured-badge { position: absolute; top: 6px; right: 6px; font-size: 0.62rem; font-weight: 800; color: #ffd75e; }
/* ── NEW ── a pet granted since you last opened this page. The grid is a hundred near-identical cards and an
   achievement pet used to land in it without a mark of any kind, so the one thing this has to survive is being
   glanced at: a filled pill, not a coloured word. It shares the top-right corner with "★ Equipped", so when
   both are on the same card the equipped line moves down a row rather than sitting underneath. */
.pet-new-badge { position: absolute; top: 6px; right: 6px; z-index: 2; font-size: 0.55rem; font-weight: 900;
    letter-spacing: 0.08em; color: #14202c; background: linear-gradient(180deg, #8ee6a0, #4fc76b);
    border-radius: 999px; padding: 2px 7px; line-height: 1.2; box-shadow: 0 0 10px rgba(79,199,107,0.55);
    animation: petNewPulse 2.2s ease-in-out infinite; }
.pet-new-badge + .pet-featured-badge { top: 26px; }
@keyframes petNewPulse { 0%, 100% { box-shadow: 0 0 6px rgba(79,199,107,0.4); } 50% { box-shadow: 0 0 14px rgba(79,199,107,0.85); } }
.pet-level-badge { position: absolute; top: 6px; left: 6px; background: rgba(0,0,0,0.35); border-radius: 999px; padding: 2px 6px; line-height: 1; }
/* Star meter (1–5) */
.pet-stars { display: inline-flex; gap: 1px; font-size: 0.62rem; letter-spacing: 0; white-space: nowrap; }
.pet-stars.lg { font-size: 1rem; gap: 2px; }
.pet-stars .on { color: #ffd75e; }
.pet-stars .off { color: rgba(255,255,255,0.22); }
/* ── THE SIXTH ── a diamond rather than a star, and it never sits quietly. Unearned it pulses faintly, which
   is the whole job of this row: telling somebody who spent months at five that five was not the end. Earned,
   it takes the colour of the stone that earned it, so a glance at the row says which rock is in the animal. */
.pet-stars .last.off { color: rgba(255,255,255,0.34); animation: petSixth 2.6s ease-in-out infinite; }
.pet-stars .last.on { color: #fff; text-shadow: 0 0 6px currentColor; }
.pet-stars.is-light .last.on { color: #ffe08a; }
.pet-stars.is-dark .last.on { color: #b061ff; }
@keyframes petSixth { 0%, 100% { opacity: .45; } 50% { opacity: 1; } }
/* Pet level bar in the detail modal */
.petx-level { text-align: left; background: rgba(255,215,94,0.08); border: 1px solid rgba(255,215,94,0.35); border-radius: 12px; padding: 10px 12px; margin: 12px 0 4px; }
.petx-level-head { display: flex; justify-content: space-between; align-items: center; font-size: 0.9rem; color: #ffe9a8; margin-bottom: 6px; }
.petx-level-bar { height: 8px; border-radius: 999px; background: rgba(255,255,255,0.1); overflow: hidden; }
.petx-level-bar > span { display: block; height: 100%; border-radius: 999px; background: linear-gradient(90deg, #ffd75e, #ff9a6a); transition: width 0.4s ease; }
/* Per-level bonus breakdown (each star's payoff) */
/* Five levels across, not five rows down — compact, and it reads as a progression track you climb. */
.petx-tiers-cap { font-size: 0.66rem; font-weight: 800; text-transform: uppercase; letter-spacing: 0.05em; color: #8b93a0; margin: 9px 0 4px; }
.petx-tiers { display: grid; grid-template-columns: repeat(5, 1fr); gap: 4px; }
.petx-tier { display: flex; flex-direction: column; align-items: center; gap: 1px; font-size: 0.78rem; padding: 5px 2px; border-radius: 9px; color: #9a93a6; background: rgba(255,255,255,0.03); border: 1px solid transparent; }
.petx-tier-stars { font-size: 0.68rem; font-weight: 800; color: rgba(255,215,94,0.5); }
.petx-tier-val { font-weight: 800; }
.petx-tier.is-done { color: #cbd2da; }
.petx-tier.is-done .petx-tier-stars { color: #ffd75e; }
.petx-tier.is-current { background: rgba(255,215,94,0.18); border-color: rgba(255,215,94,0.5); color: #ffe9a8; font-weight: 900; box-shadow: 0 0 12px rgba(255,215,94,0.22); }
.petx-tier.is-current .petx-tier-stars { color: #ffd75e; }
.petx-tier.is-locked .petx-tier-stars { color: rgba(255,255,255,0.18); }
/* Daily Spin wheel */
.spin-card { text-align: center; }
.spin-top { display: flex; justify-content: space-between; align-items: baseline; gap: 8px; font-weight: 800; flex-wrap: wrap; }
.spin-stage { position: relative; width: min(320px, 82vw); height: min(320px, 82vw); margin: 14px auto 6px; }
.spin-pointer { position: absolute; top: -6px; left: 50%; transform: translateX(-50%); font-size: 1.8rem; color: #ffd75e; z-index: 3; filter: drop-shadow(0 2px 3px rgba(0,0,0,0.6)); }
.spin-wheel { position: absolute; inset: 0; border-radius: 50%; border: 6px solid #ffd75e; box-shadow: 0 0 30px rgba(255,215,94,0.35), inset 0 0 20px rgba(0,0,0,0.5); }
.spin-seg-label { position: absolute; inset: 0; display: flex; justify-content: center; }
.spin-seg-emoji { position: absolute; top: 14px; font-size: clamp(1rem, 5vw, 1.5rem); }
.spin-hub { position: absolute; inset: 0; margin: auto; width: 46px; height: 46px; border-radius: 50%; background: #16181e; border: 3px solid #ffd75e; display: flex; align-items: center; justify-content: center; font-size: 1.3rem; }
.spin-result { margin: 8px auto; font-size: 1.05rem; color: #ffe9a8; animation: petLevelPop 0.6s ease; }
.spin-msg { margin: 6px auto; font-size: 0.9rem; color: #ff8a8a; }
.spin-actions { display: flex; gap: 8px; justify-content: center; flex-wrap: wrap; margin-top: 4px; }
.spin-go { font-size: 1rem; padding: 10px 26px; }
.spin-buy { padding: 10px 18px; font-size: 0.9rem; font-weight: 700; border-radius: 999px; border: 1px solid #3a3f47; background: #23262c; color: #ffd75e; cursor: pointer; }
.spin-buy:disabled { opacity: 0.5; cursor: default; }
.spin-next, .spin-hint { font-size: 0.78rem; margin: 8px 0 0; }
.spin-lead { font-size: 0.82rem; margin: 2px 0 0; }
.spin-seg-emoji.tier-jackpot { filter: drop-shadow(0 0 6px #ffd75e); font-size: clamp(1.15rem, 5.5vw, 1.7rem); }
.spin-seg-emoji.tier-mini { filter: drop-shadow(0 0 5px #c99bff); }
.spin-seg-emoji.tier-rare { filter: drop-shadow(0 0 4px #5ce0c0); }
.spin-result.tier-jackpot { color: #ffd75e; font-weight: 900; font-size: 1.2rem; text-shadow: 0 0 12px rgba(255,215,94,0.6); }
.spin-result.tier-mini { color: #c99bff; font-weight: 800; }
.spin-result.tier-rare { color: #7ff0d6; }
/* Wheel legend — every prize + its real odds (jackpot deliberately tiny). */
.spin-legend { margin-top: 14px; text-align: left; }
.spin-legend-head { font-weight: 800; font-size: 0.82rem; color: #cdbfa6; margin-bottom: 6px; }
.spin-legend-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 5px; }
.spin-legend-item { display: flex; align-items: center; gap: 6px; padding: 4px 8px; border-radius: 8px; background: rgba(255,255,255,0.03); border: 1px solid rgba(255,255,255,0.06); font-size: 0.76rem; min-width: 0; /* let the 1fr track shrink so the odds never overflow off-screen */ }
.spin-legend-emoji { font-size: 0.95rem; flex: 0 0 auto; }
.spin-legend-label { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.spin-legend-odds { color: #8a9099; font-weight: 700; font-size: 0.7rem; flex: 0 0 auto; }
/* Jackpot + mini span the full width so their (longer) prize labels are legible and stand out. */
.spin-legend-item.tier-jackpot, .spin-legend-item.tier-mini { grid-column: 1 / -1; padding: 6px 10px; }
.spin-legend-item.tier-jackpot { border-color: rgba(255,215,94,0.55); background: rgba(255,215,94,0.1); }
.spin-legend-item.tier-jackpot .spin-legend-label { color: #ffd75e; font-weight: 800; }
.spin-legend-item.tier-jackpot .spin-legend-emoji { font-size: 1.15rem; }
.spin-legend-item.tier-mini { border-color: rgba(201,155,255,0.5); background: rgba(176,97,255,0.1); }
.spin-legend-item.tier-mini .spin-legend-label { color: #c99bff; font-weight: 800; }
.spin-legend-item.tier-rare { border-color: rgba(92,224,192,0.35); }
/* Jackpot / mini-jackpot celebration overlay */
.spin-celebrate { position: fixed; inset: 0; z-index: 1300; display: flex; align-items: center; justify-content: center; background: rgba(6,7,10,0.72); backdrop-filter: blur(3px); animation: petxFade 0.2s ease; }
.spin-celebrate-card { position: relative; text-align: center; background: linear-gradient(180deg,#1b1e26,#12141a); border: 2px solid #ffd75e; border-radius: 20px; padding: 26px 30px; box-shadow: 0 0 50px rgba(255,215,94,0.5); animation: petLevelPop 0.5s cubic-bezier(.2,.9,.3,1.3); }
.spin-celebrate-mini .spin-celebrate-card { border-color: #c99bff; box-shadow: 0 0 50px rgba(176,97,255,0.5); }
.spin-celebrate-emoji { font-size: 4rem; }
.spin-celebrate-title { font-size: 1.8rem; font-weight: 900; letter-spacing: 0.04em; color: #ffd75e; }
.spin-celebrate-mini .spin-celebrate-title { color: #c99bff; }
.spin-celebrate-sub { font-size: 1.1rem; font-weight: 800; margin: 4px 0 14px; }
.spin-celebrate-confetti { position: absolute; inset: 0; overflow: hidden; pointer-events: none; }
.spin-celebrate-confetti span { position: absolute; top: -14px; width: 9px; height: 14px; border-radius: 2px; animation: spinConfetti 3.2s linear forwards; }
@keyframes spinConfetti { 0% { transform: translateY(-14px) rotate(0); opacity: 1; } 100% { transform: translateY(100vh) rotate(720deg); opacity: 0.5; } }
/* In-game menu bar — hop between game areas without returning to the hub. */
.game-nav { margin: 0 0 14px; display: flex; align-items: center; gap: 8px; }
.game-nav-gold { flex: 0 0 auto; display: inline-flex; align-items: center; gap: 3px; padding: 7px 12px; border-radius: 999px; font-size: 0.85rem; font-weight: 900; color: #ffd75e; background: rgba(255,215,94,0.14); border: 1px solid rgba(255,215,94,0.45); white-space: nowrap; }
.game-nav-scroll { flex: 1; min-width: 0; display: flex; gap: 6px; overflow-x: auto; padding: 2px 2px 6px; scrollbar-width: none; -webkit-overflow-scrolling: touch; }
.game-nav-scroll::-webkit-scrollbar { display: none; }
.game-nav-link { flex: 0 0 auto; display: inline-flex; align-items: center; gap: 4px; padding: 7px 13px; border-radius: 999px; font-size: 0.82rem; font-weight: 700; text-decoration: none; color: #cdd2d8; background: rgba(255,255,255,0.05); border: 1px solid rgba(255,255,255,0.12); white-space: nowrap; }
.game-nav-link:hover { border-color: rgba(255,215,94,0.5); }
.game-nav-link.is-active { background: rgba(255,215,94,0.16); border-color: rgba(255,215,94,0.6); color: #ffd75e; }
/* Unopened-chest reminder badge on the Gear pill. */
.game-nav-link.has-badge { border-color: rgba(255,215,94,0.6); color: #ffd75e; }
.game-nav-badge { display: inline-flex; align-items: center; justify-content: center; min-width: 18px; height: 18px; padding: 0 5px; margin-left: 2px; border-radius: 999px; background: #ff4d4d; color: #fff; font-size: 0.72rem; font-weight: 900; line-height: 1; box-shadow: 0 0 0 2px rgba(255,77,77,0.25); animation: rar-pulse 2s ease-in-out infinite; }
/* Red-alert dot: the boat has landed and needs tending (Sailing pill). */
.game-nav-link.has-dot { border-color: rgba(255,77,77,0.6); color: #ffb3b3; }
.game-nav-dot { width: 9px; height: 9px; margin-left: 2px; border-radius: 50%; background: #ff4d4d; box-shadow: 0 0 0 2px rgba(255,77,77,0.25), 0 0 6px rgba(255,77,77,0.7); animation: rar-pulse 1.6s ease-in-out infinite; }

/* Badge passive summary on the badges hub. */
.badge-passive-strip { margin: 8px 0 0; padding: 7px 12px; border-radius: 10px; font-size: 0.84rem; color: #ffe9a8;
    background: rgba(255,215,94,0.1); border: 1px solid rgba(255,215,94,0.35); }

/* ── Badges hub hero: compact title + juiced "Badge Power" panel ── */
.badges-hero { background: radial-gradient(120% 130% at 50% -10%, rgba(255,215,94,0.09), transparent 62%); }
.bh-head { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.bh-head h1 { margin: 0; font-size: 1.5rem; }
.bh-count { display: inline-flex; align-items: baseline; gap: 4px; font-size: 0.9rem; color: #9aa2ab; font-weight: 700; }
.bh-count b { font-size: 1.5rem; color: #ffd75e; font-weight: 900; }
.bh-power { margin-top: 12px; }
.bh-power-label { font-size: 11px; font-weight: 900; letter-spacing: 0.06em; text-transform: uppercase; color: #ffcf6a; margin-bottom: 10px; }
.bh-power-label span { color: #8a8f97; letter-spacing: 0; text-transform: none; font-weight: 700; }
.bh-domains { display: flex; flex-direction: column; gap: 10px; }
.bh-domain { border-radius: 14px; padding: 11px 12px 12px; border: 1px solid color-mix(in srgb, var(--acc) 32%, transparent);
    background: linear-gradient(180deg, color-mix(in srgb, var(--acc) 12%, transparent), rgba(255,255,255,0.015)); }
.bh-domain-head { display: flex; align-items: baseline; gap: 7px; margin-bottom: 9px; }
.bh-domain-ico { font-size: 1rem; }
.bh-domain-head b { font-size: 12.5px; font-weight: 900; letter-spacing: 0.03em; color: var(--acc); }
.bh-domain-head em { font-size: 10.5px; font-style: normal; color: #8a8f97; font-weight: 600; }
.bh-domain-tiles { display: grid; grid-template-columns: repeat(auto-fill, minmax(88px, 1fr)); gap: 8px; }
.bh-stat { display: flex; flex-direction: column; align-items: center; gap: 1px; padding: 9px 6px; border-radius: 11px; text-align: center;
    background: color-mix(in srgb, var(--acc) 9%, rgba(0,0,0,0.18)); border: 1px solid color-mix(in srgb, var(--acc) 22%, transparent); }
.bh-stat-ico { font-size: 1.15rem; line-height: 1; filter: drop-shadow(0 2px 4px rgba(0,0,0,0.4)); }
.bh-stat-val { font-size: 1.25rem; font-weight: 900; line-height: 1.05; color: #fff; text-shadow: 0 0 14px var(--acc); font-variant-numeric: tabular-nums; }
.bh-stat-lab { font-size: 9.5px; font-weight: 800; letter-spacing: 0.02em; text-transform: uppercase; color: color-mix(in srgb, var(--acc) 62%, #cfd4da); }
.bh-power-empty { font-size: 0.86rem; color: #b6bcc4; padding: 10px 12px; border-radius: 12px; background: rgba(255,255,255,0.03); border: 1px dashed rgba(255,255,255,0.14); }
.bh-power-empty b { color: #ffe9a8; }

/* ── Collapsible chrome (showcase + shop) below the collection ── */
.badges-collapse { padding-top: 14px; padding-bottom: 14px; }
.badges-collapse > summary { display: flex; align-items: center; gap: 10px; cursor: pointer; list-style: none; font-weight: 800; }
.badges-collapse > summary::-webkit-details-marker { display: none; }
.badges-collapse > summary::after { content: "▸"; margin-left: auto; color: #9aa2ab; font-size: 0.9rem; transition: transform .18s; }
.badges-collapse[open] > summary::after { transform: rotate(90deg); }
.bc-sum-title { font-size: 1rem; }
.bc-sum-hint { font-size: 11px; font-weight: 700; color: #9aa2ab; padding: 2px 8px; border-radius: 999px; background: rgba(255,255,255,0.06); }

/* THE GAME hub — the single game area's dopamine menu. */
.game-hub-hero { text-align: center; background: radial-gradient(120% 120% at 50% 0%, rgba(255,215,94,0.12), transparent 60%); }
.game-hub-stats { margin-top: 12px; }
.game-hub-chips { display: flex; flex-wrap: wrap; gap: 8px; justify-content: center; }
.game-hub-chip { font-weight: 800; font-size: 0.82rem; padding: 4px 12px; border-radius: 999px; background: rgba(255,255,255,0.06); border: 1px solid rgba(255,255,255,0.12); }
.game-hub-chip.is-live { background: rgba(255,215,94,0.16); border-color: rgba(255,215,94,0.5); color: #ffd75e; text-decoration: none; animation: rar-pulse 2.5s ease-in-out infinite; }
.game-hub-progress { margin-top: 10px; max-width: 420px; margin-left: auto; margin-right: auto; }
.game-hub-bar { height: 8px; border-radius: 999px; background: rgba(255,255,255,0.1); overflow: hidden; margin-bottom: 4px; }
.game-hub-bar > span { display: block; height: 100%; background: linear-gradient(90deg, #ffd75e, #ffb020); border-radius: 999px; }
.game-hub-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(150px, 1fr)); gap: 12px; }
.game-tile { display: flex; flex-direction: column; gap: 4px; padding: 16px 14px; border-radius: 16px; text-decoration: none; color: inherit;
    background: linear-gradient(180deg, rgba(255,255,255,0.05), rgba(255,255,255,0.02)); border: 1px solid rgba(255,255,255,0.12);
    transition: transform 0.12s ease, border-color 0.12s ease, box-shadow 0.12s ease; }
