/* Today's Deals — rotating discounted shop */
.deals-card { border: 1px solid rgba(255,154,106,0.4); background: linear-gradient(180deg, rgba(255,154,106,0.06), transparent 60%); }
.deals-head { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; }
