/* Tap-to-inspect on a deal */
.deal-inspect { display: flex; flex-direction: column; align-items: center; gap: 4px; background: none; border: none; padding: 0; cursor: pointer; color: inherit; width: 100%; }
.deal-sheet-overlay { position: fixed; inset: 0; z-index: 1250; display: flex; align-items: center; justify-content: center; background: rgba(0,0,0,0.78); padding: 20px; }
.deal-sheet { width: 100%; max-width: 320px; margin: 0; text-align: center; border-width: 2px; }
