.deal-btn:disabled { background: #23262c; color: #7c828b; border-color: #2a2f37; cursor: default; }
/* Escalating per-level flair on the pet icon (cards + modal hero). Higher level = cooler. */
.pet-icon, .petx-hero-icon { position: relative; transition: filter 0.3s ease; }
.pet-icon[data-petlvl="2"], .petx-hero-icon[data-petlvl="2"] { filter: drop-shadow(0 0 5px rgba(255,215,94,0.45)); }
.pet-icon[data-petlvl="3"], .petx-hero-icon[data-petlvl="3"] { filter: drop-shadow(0 0 8px rgba(255,215,94,0.6)); }
.pet-icon[data-petlvl="4"], .petx-hero-icon[data-petlvl="4"] { filter: drop-shadow(0 0 11px rgba(255,180,74,0.75)); }
.pet-icon[data-petlvl="5"], .petx-hero-icon[data-petlvl="5"] { filter: drop-shadow(0 0 14px rgba(255,180,74,0.95)); animation: petAuraPulse 2.2s ease-in-out infinite; }
@keyframes petAuraPulse {
    0%, 100% { filter: drop-shadow(0 0 10px rgba(255,180,74,0.7)); }
    50% { filter: drop-shadow(0 0 18px rgba(255,120,60,1)); }
}
/* Sparkles: Lv4 one drifting spark, Lv5 two. Pseudo-elements float around the icon. */
.pet-icon[data-petlvl="4"]::after, .pet-icon[data-petlvl="5"]::after,
.petx-hero-icon[data-petlvl="4"]::after, .petx-hero-icon[data-petlvl="5"]::after {
    content: "✨"; position: absolute; top: -6px; right: -8px; font-size: 0.7em; pointer-events: none;
    animation: petSparkle 1.8s ease-in-out infinite;
}
.pet-icon[data-petlvl="5"]::before, .petx-hero-icon[data-petlvl="5"]::before {
    content: "⭐"; position: absolute; bottom: -4px; left: -8px; font-size: 0.55em; pointer-events: none;
    animation: petSparkle 2.3s ease-in-out infinite 0.6s;
}
@keyframes petSparkle {
    0%, 100% { opacity: 0; transform: translateY(2px) scale(0.6); }
    50% { opacity: 1; transform: translateY(-4px) scale(1); }
}
/* A Lv3+ gold ring behind the card icon. */
.pet-icon[data-petlvl="3"], .pet-icon[data-petlvl="4"], .pet-icon[data-petlvl="5"] { border-radius: 50%; box-shadow: 0 0 0 2px rgba(255,215,94,0.35); }
/* Evolution reveal: old sprite flashes out, new evolved sprite bursts in (Pokémon-style). */
.petx-evo { position: relative; width: 168px; height: 168px; margin: 0 auto; animation: petEvoPop 2s ease both; }
.petx-evo-img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: contain; }
.petx-evo-old { animation: evoOldOut 2s ease both; }
.petx-evo-new { opacity: 0; animation: evoNewIn 2s ease both; filter: drop-shadow(0 0 14px rgba(255,200,90,0.9)); }
.petx-evo .petx-evo-new:only-child { opacity: 1; animation: none; } /* static (no old form) case */
.petx-evo-flash { position: absolute; inset: -20% ; border-radius: 50%; pointer-events: none;
    background: radial-gradient(circle, rgba(255,255,255,0.95) 0%, rgba(255,230,160,0.5) 40%, transparent 70%);
    opacity: 0; animation: evoFlash 2s ease both; }
@keyframes evoOldOut { 0%, 52% { opacity: 1; } 60% { opacity: 0.15; } 66% { opacity: 0.6; } 72% { opacity: 0.1; } 100% { opacity: 0; } }
@keyframes evoNewIn { 0%, 66% { opacity: 0; } 76% { opacity: 1; } 100% { opacity: 1; } }
@keyframes evoFlash { 0%, 55% { opacity: 0; } 70% { opacity: 1; } 100% { opacity: 0; } }
@keyframes petEvoPop { 0%, 60% { transform: scale(1); } 74% { transform: scale(1.16); } 100% { transform: scale(1); } }
/* Level-up celebration flourish */
.petx-levelup .petx-cele-tag { background: linear-gradient(90deg,#ffd75e,#ff9a6a); color: #0f0f12; }
.petx-levelup .pet-stars { margin: 6px 0 10px; justify-content: center; display: flex; }
.petx-levelup .petx-hero-icon { animation: petLevelPop 0.6s ease; }
@keyframes petLevelPop { 0% { transform: scale(0.6) rotate(-8deg); opacity: 0; } 55% { transform: scale(1.15) rotate(4deg); } 100% { transform: scale(1) rotate(0); opacity: 1; } }
.pet-card.just-equipped { animation: petPop 0.5s ease; }
@keyframes petPop { 0% { transform: scale(1); } 40% { transform: scale(1.09); } 100% { transform: scale(1); } }
.pet-give { background: none; border: none; color: #8fb8ff; font-size: 0.68rem; cursor: pointer; padding: 0; margin-top: 2px; }
.pet-give:hover { text-decoration: underline; }
.pet-traded { font-size: 0.64rem; color: #6a7078; margin-top: 2px; }

/* Pet gift modal + receive celebration — proper in-app dialogs (no browser prompts). */
.petx-overlay { position: fixed; inset: 0; z-index: 1000; display: flex; align-items: center; justify-content: center; padding: 20px; background: rgba(6,7,10,0.72); backdrop-filter: blur(4px); animation: petxFade 0.2s ease; }
@keyframes petxFade { from { opacity: 0; } to { opacity: 1; } }
.petx-modal, .petx-cele { position: relative; width: 100%; max-width: 380px; background: linear-gradient(180deg, #1b1e26, #12141a); border: 1px solid #2a2f37; border-radius: 20px; padding: 24px 20px 20px; text-align: center; box-shadow: 0 24px 60px rgba(0,0,0,0.55); animation: petxPop 0.28s cubic-bezier(.2,.9,.3,1.2); }
@keyframes petxPop { 0% { transform: translateY(12px) scale(0.94); opacity: 0; } 100% { transform: translateY(0) scale(1); opacity: 1; } }
.petx-close { position: absolute; top: 10px; right: 12px; background: none; border: none; color: #9a93a6; font-size: 1.5rem; line-height: 1; cursor: pointer; }
.petx-hero { position: relative; width: 108px; height: 108px; margin: 4px auto 12px; display: flex; align-items: center; justify-content: center; }
.petx-hero-big { width: 132px; height: 132px; }
.petx-hero-icon { font-size: 4.4rem; position: relative; z-index: 1; filter: drop-shadow(0 4px 10px rgba(0,0,0,0.5)); animation: petxFloat 3s ease-in-out infinite; }
