@keyframes petxFloat { 0%,100% { transform: translateY(0); } 50% { transform: translateY(-6px); } }
.petx-hero-glow { position: absolute; inset: -12%; border-radius: 50%; background: radial-gradient(circle, var(--glow, #ffd75e) 0%, transparent 68%); opacity: 0.5; animation: petxPulse 2.4s ease-in-out infinite; }
@keyframes petxPulse { 0%,100% { transform: scale(0.9); opacity: 0.4; } 50% { transform: scale(1.12); opacity: 0.65; } }
.petx-modal.rarity-common, .petx-cele.rarity-common { --glow: #9aa0a6; }
.petx-modal.rarity-rare, .petx-cele.rarity-rare { --glow: #4aa3ff; }
.petx-modal.rarity-epic, .petx-cele.rarity-epic { --glow: #b76bff; }
.petx-modal.rarity-legendary, .petx-cele.rarity-legendary { --glow: #ffb020; }
.petx-modal.rarity-mythic, .petx-cele.rarity-mythic { --glow: #33e0a1; }
.petx-modal.rarity-ascendant, .petx-cele.rarity-ascendant { --glow: #ff7a3c; }
.petx-modal.rarity-eternal, .petx-cele.rarity-eternal { --glow: #ff5cc8; }
.petx-title { margin: 4px 0 2px; font-size: 1.25rem; }
.petx-sub { margin: 0 0 12px; color: #9a93a6; font-size: 0.88rem; }
.petx-warn { background: rgba(255,215,94,0.1); border: 1px solid rgba(255,215,94,0.35); color: #ffe8a8; border-radius: 12px; padding: 10px 12px; font-size: 0.8rem; margin-bottom: 14px; }
.petx-label { display: block; text-align: left; font-size: 0.78rem; font-weight: 700; color: #cbd2da; margin-bottom: 4px; }
.petx-input { width: 100%; padding: 12px 14px; border-radius: 12px; background: #0e1015; border: 1px solid #3a3f47; color: #fff; font-size: 1rem; }
.petx-input:focus { outline: none; border-color: var(--glow, #ffd75e); }
.petx-err { color: #ff8a8a; font-size: 0.82rem; margin: 8px 0 0; }
.petx-actions { display: flex; gap: 10px; margin-top: 16px; }
.petx-actions button { flex: 1; padding: 12px; }
/* The arrival card gained a way through to the pet itself, so its primary control is now an anchor — and the
   site-wide link colour would paint a gold button's label blue. Stated here, on the anchor. */
.petx-celebrate a.btn-gold { display: inline-block; color: #241a05; text-decoration: none; }
.petx-celebrate a.btn-gold:hover, .petx-celebrate a.btn-gold:focus-visible { color: #241a05; }
.petx-cele-later { display: block; margin: 8px auto 0; padding: 6px 14px; background: none; border: 0; cursor: pointer;
    font-size: 0.78rem; font-weight: 800; color: rgba(255,255,255,0.55); }
.petx-cele-later:hover, .petx-cele-later:focus-visible { color: rgba(255,255,255,0.85); }
.petx-cele-tag { display: inline-block; font-size: 0.7rem; font-weight: 800; letter-spacing: 0.08em; text-transform: uppercase; color: #0e1015; background: var(--glow, #ffd75e); padding: 3px 12px; border-radius: 999px; margin-bottom: 4px; }
.petx-confetti { position: absolute; inset: 0; overflow: hidden; pointer-events: none; border-radius: 20px; }
.petx-confetti span { position: absolute; top: -10%; left: calc((var(--i) + 1) * 6.5%); font-size: 1rem; animation: petxFall 1.6s ease-in forwards; animation-delay: calc(var(--i) * 0.06s); opacity: 0; }
@keyframes petxFall { 0% { transform: translateY(-20px) rotate(0); opacity: 0; } 15% { opacity: 1; } 100% { transform: translateY(320px) rotate(320deg); opacity: 0; } }
.quest-claim { flex: 0 0 auto; padding: 7px 14px; }
.quest-check { flex: 0 0 auto; color: #7ad07a; font-size: 1.3rem; font-weight: 900; }

/* Claim celebration — flash, coin burst, gold count-up (reuses chest-fade/flash/pop keyframes). */
.quest-cele { position: fixed; inset: 0; z-index: 3000; display: grid; place-items: center; padding: 24px; overflow: hidden;
    background: radial-gradient(circle at 50% 44%, rgba(34, 24, 6, 0.86), rgba(3, 2, 6, 0.94)); backdrop-filter: blur(5px); -webkit-backdrop-filter: blur(5px); animation: chest-fade 0.2s ease; }
.quest-cele-flash { position: fixed; inset: -20%; z-index: 1; pointer-events: none;
    background: radial-gradient(circle at 50% 44%, #fff 0%, #ffd75e 34%, transparent 70%); animation: chest-flash 0.55s ease-out forwards; }
.quest-cele-inner { position: relative; z-index: 2; display: flex; flex-direction: column; align-items: center; gap: 8px; text-align: center;
    animation: chest-pop 0.5s cubic-bezier(0.2, 1.5, 0.4, 1); }
.quest-cele-badge { font-size: clamp(3rem, 15vw, 4.4rem); line-height: 1; filter: drop-shadow(0 0 18px rgba(122, 208, 122, 0.8)); animation: quest-badge 0.55s cubic-bezier(0.2, 1.6, 0.4, 1); }
@keyframes quest-badge { 0% { transform: scale(0) rotate(-20deg); } 60% { transform: scale(1.2); } 100% { transform: scale(1) rotate(0); } }
.quest-cele-title { font-weight: 900; font-size: clamp(1.1rem, 5vw, 1.6rem); color: #ffd75e; letter-spacing: 0.04em; text-transform: uppercase; text-shadow: 0 2px 10px rgba(0,0,0,0.6), 0 0 18px rgba(255,180,60,0.6); }
.quest-cele-gold { font-weight: 900; font-size: clamp(2.1rem, 9vw, 3.2rem); color: #fff; line-height: 1; font-variant-numeric: tabular-nums; text-shadow: 0 3px 14px #000, 0 0 26px rgba(255,200,80,0.85); }
.quest-cele-chest { font-weight: 800; font-size: 1rem; color: #ffd75e; }
.quest-cele-coins { position: absolute; inset: 0; z-index: -1; pointer-events: none; }
.quest-coin { position: absolute; left: 50%; top: 42%; width: var(--sz, 10px); height: var(--sz, 10px); border-radius: 50%;
    background: radial-gradient(circle at 35% 30%, #fff3b0, #ffd75e 55%, #c8961e); box-shadow: 0 0 8px rgba(255,200,80,0.85);
    transform: translate(-50%, -50%); opacity: 0; animation: quest-coin 1.05s cubic-bezier(0.15, 0.7, 0.3, 1) forwards; }
@keyframes quest-coin {
    0% { opacity: 0; transform: translate(-50%, -50%) scale(0.3) rotate(0deg); }
    12% { opacity: 1; }
    100% { opacity: 0; transform: translate(calc(-50% + var(--tx)), calc(-50% + var(--ty))) scale(1) rotate(var(--rot)); }
}
.quest-cele-inner .button.gold { margin-top: 6px; min-width: 130px; }

/* ============ Loot chests + reveal ============ */
.chest-card { border-color: rgba(255, 215, 94, 0.35); }
.chest-total { float: right; background: #e0443a; color: #fff; font-size: 0.8rem; font-weight: 800; border-radius: 999px; padding: 1px 9px; }
/* `align-items: stretch` is the grid default, but the TILE has to pass it on: a stack tile carries a second
   button and a single chest does not, so without the chest art growing to fill the difference the row came out
   ragged — the Gold Chest sitting a button shorter than the two beside it. */
.chest-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(96px, 1fr)); gap: 10px; align-items: stretch; }
/* ── THE TILE IS A CONTAINER NOW, NOT A BUTTON ───────────────────────────────────────────────────────────────
   It carries two controls — open one, open the stack — so the frame moved off the button and onto a wrapper,
   and the rules that only ever applied to a button (`:disabled`, the whole-tile `:hover` lift) moved with
   them onto the inner control. Left where they were, `.chest-tile:disabled` would simply never match again
   and a disabled stack would have gone on looking tappable. */
.chest-tile {
    display: flex; flex-direction: column; align-items: stretch; gap: 6px;
    padding: 12px 6px; border-radius: 14px; background: rgba(0, 0, 0, 0.3);
    border: 1.5px solid var(--chest, #b08a52); box-shadow: 0 0 14px -6px var(--chest);
    transition: transform 0.12s ease, box-shadow 0.12s ease;
}
.chest-tile:has(.chest-tile-one:hover) { transform: translateY(-3px) scale(1.03); box-shadow: 0 0 20px -4px var(--chest); }
.chest-tile-one {
    display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 2px; cursor: pointer;
    font: inherit; color: #e7dcc4; background: none; border: 0; padding: 0; width: 100%; flex: 1;
}
.chest-tile-one:disabled { opacity: 0.6; cursor: default; }
/* The stack button is deliberately quieter than the chest above it: opening one is the ordinary gesture and
   this is the shortcut, not the headline. */
.chest-tile-all {
    padding: 5px 8px; border-radius: 9px; cursor: pointer; font-size: 11px; font-weight: 900; letter-spacing: .01em;
    color: var(--chest, #e7dcc4); background: color-mix(in srgb, var(--chest) 14%, transparent);
    border: 1px solid color-mix(in srgb, var(--chest) 45%, transparent);
}
.chest-tile-all:hover:not(:disabled) { background: color-mix(in srgb, var(--chest) 26%, transparent); }
.chest-tile-all:disabled { opacity: 0.5; cursor: default; }
.chest-openall {
    display: block; width: 100%; margin-top: 10px; padding: 12px; border-radius: 13px; cursor: pointer;
    font-size: 0.9rem; font-weight: 900; color: #2a1a00;
    background: linear-gradient(180deg, #ffe08a, #f0b73c); border: 1px solid rgba(255,240,190,0.5);
}
.chest-openall:disabled { opacity: 0.5; cursor: default; }

/* ── THE SUMMARY, FOR A PILE ─────────────────────────────────────────────────────────────────────────────────
   Rows, best first, each tinted by its own rarity — the same reading the single-chest celebration gives you,
   compressed to one line so twenty-eight of them fit on one card. */
/* `.chest-reveal` carries no surface of its own — the single-chest celebration is a full-screen burst with no
   card behind it, which is right for one dramatic object and wrong for a list. The summary needs a real card
   or the page reads straight through the gaps between its rows. */
.chest-bulk { max-width: 420px; width: 100%; padding: 18px 16px 16px; border-radius: 20px;
    background: linear-gradient(180deg, #221a2c, #120d18);
    border: 1px solid color-mix(in srgb, var(--r, #ffd75e) 40%, rgba(255,255,255,0.12));
    box-shadow: 0 26px 70px rgba(0,0,0,0.8), 0 0 50px -18px var(--r, #ffd75e); }
.chest-bulk-head { text-align: center; padding-bottom: 10px; }
.chest-bulk-head b { display: block; font-size: 1.35rem; color: var(--r, #ffd75e); }
.chest-bulk-head em { font-style: normal; font-size: 0.78rem; color: #9aa2ab; }
.chest-bulk-list { display: grid; gap: 5px; max-height: 52dvh; overflow-y: auto; }
.chest-bulk-row {
    display: grid; grid-template-columns: 1fr auto auto; align-items: baseline; gap: 8px;
    padding: 8px 11px; border-radius: 10px; text-align: left;
    background: color-mix(in srgb, var(--r) 10%, rgba(255,255,255,0.04));
    border: 1px solid color-mix(in srgb, var(--r) 34%, transparent);
}
.chest-bulk-row b { font-size: 0.86rem; font-weight: 800; color: var(--r, #e7dcc4); min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.chest-bulk-row span { font-size: 0.7rem; color: #96a0ac; }
.chest-bulk-row em { font-style: normal; font-size: 0.86rem; font-weight: 900; color: #fff; font-variant-numeric: tabular-nums; }
.chest-emoji { font-size: 2rem; line-height: 1; filter: drop-shadow(0 2px 4px rgba(0,0,0,0.5)); }
.chest-img { width: 64px; height: 64px; object-fit: contain; filter: drop-shadow(0 3px 6px rgba(0,0,0,0.55)) drop-shadow(0 0 10px color-mix(in srgb, var(--chest, #ffd75e) 45%, transparent)); }
.chest-name { font-size: 0.72rem; font-weight: 700; }
.chest-count { font-size: 0.8rem; font-weight: 800; color: var(--chest); }

/* Reveal modal — full-screen celebration (portaled to <body> so it always covers the viewport). */
.chest-modal { position: fixed; inset: 0; z-index: 3000; display: grid; place-items: center; padding: 24px;
    background: radial-gradient(circle at 50% 42%, rgba(24, 16, 38, 0.9), rgba(3, 2, 6, 0.97));
    backdrop-filter: blur(6px); -webkit-backdrop-filter: blur(6px); animation: chest-fade 0.22s ease; overflow: hidden; }
@keyframes chest-fade { from { opacity: 0; } to { opacity: 1; } }
.chest-stage { position: relative; display: flex; flex-direction: column; align-items: center; justify-content: center;
    gap: 16px; width: 100%; max-width: 420px; text-align: center; }

/* Anticipation: the chest rattles over a swelling glow. */
.chest-glowpad { position: absolute; width: 300px; height: 300px; border-radius: 50%;
    background: radial-gradient(circle, color-mix(in srgb, var(--chest, #ffd75e) 70%, transparent) 0%, transparent 65%);
    filter: blur(6px); animation: chest-glowpad 1.5s ease-in-out infinite; }
@keyframes chest-glowpad { 0%, 100% { opacity: 0.25; transform: scale(0.85); } 50% { opacity: 0.6; transform: scale(1.1); } }
.chest-shake { position: relative; z-index: 1; }
.chest-img-big { width: clamp(180px, 60vw, 240px); height: clamp(180px, 60vw, 240px); object-fit: contain;
    filter: drop-shadow(0 0 30px var(--chest, #ffd75e)); animation: chest-rattle 0.42s ease-in-out infinite; transform-origin: 50% 80%; }
.chest-opening { position: relative; z-index: 1; color: #ffd75e; font-weight: 900; letter-spacing: 0.16em;
    text-transform: uppercase; font-size: 1rem; animation: chest-pulse 0.9s ease-in-out infinite; }
@keyframes chest-rattle {
    0%, 100% { transform: rotate(-6deg) translateY(0) scale(1); }
    20% { transform: rotate(7deg) translateY(-8px) scale(1.03); }
    40% { transform: rotate(-8deg) translateY(0) scale(1); }
    60% { transform: rotate(6deg) translateY(-5px) scale(1.02); }
    80% { transform: rotate(-4deg) translateY(0) scale(1); }
}
@keyframes chest-pulse { 0%, 100% { opacity: 0.55; } 50% { opacity: 1; } }

/* Reveal: a full-bleed flash, rotating light rays, an outward particle burst, and the reward slamming in. */
.chest-flash { position: fixed; inset: -20%; z-index: 1; pointer-events: none;
    background: radial-gradient(circle at 50% 45%, #fff 0%, var(--rar, #ffd75e) 34%, transparent 70%);
    animation: chest-flash 0.6s ease-out forwards; }
@keyframes chest-flash { 0% { opacity: 0.95; } 100% { opacity: 0; } }
.chest-reward-wrap { position: relative; display: flex; align-items: center; justify-content: center; }
.chest-reward-wrap.slam { animation: chest-slam 0.55s cubic-bezier(0.18, 1.5, 0.4, 1); }
@keyframes chest-slam { 0% { transform: scale(0.5); } 55% { transform: scale(1.08); } 70% { transform: scale(0.97); } 100% { transform: scale(1); } }
.chest-rays { position: absolute; width: 460px; height: 460px; z-index: -2; border-radius: 50%; opacity: 0.22;
    background: repeating-conic-gradient(from 0deg, var(--rar, #ffd75e) 0deg 7deg, transparent 7deg 20deg);
    -webkit-mask: radial-gradient(circle, #000 8%, transparent 62%); mask: radial-gradient(circle, #000 8%, transparent 62%);
    animation: chest-rays 9s linear infinite; }
@keyframes chest-rays { to { transform: rotate(360deg); } }
.chest-particles { position: absolute; inset: 0; z-index: -1; pointer-events: none; }
.chest-particle { position: absolute; left: 50%; top: 46%; width: var(--sz, 8px); height: var(--sz, 8px);
    background: var(--pc, #ffd75e); box-shadow: 0 0 8px var(--pc, #ffd75e); transform: translate(-50%, -50%);
    opacity: 0; animation: chest-particle 1.05s cubic-bezier(0.15, 0.7, 0.3, 1) forwards; }
.chest-particle.round { border-radius: 50%; }
@keyframes chest-particle {
    0% { opacity: 0; transform: translate(-50%, -50%) scale(0.3) rotate(0deg); }
    12% { opacity: 1; }
    100% { opacity: 0; transform: translate(calc(-50% + var(--tx)), calc(-50% + var(--ty))) scale(1) rotate(var(--rot)); }
}
.chest-reward { position: relative; display: flex; flex-direction: column; align-items: center; gap: 8px;
    padding: 28px 22px; border-radius: 20px; background: rgba(6, 5, 12, 0.72);
    border: 2px solid var(--rar, #9aa7b5); box-shadow: 0 0 60px -8px var(--rar), inset 0 0 24px -12px var(--rar);
    animation: chest-pop 0.5s cubic-bezier(0.2, 1.5, 0.4, 1); }
@keyframes chest-pop { 0% { transform: scale(0.4); opacity: 0; } 60% { transform: scale(1.08); } 100% { transform: scale(1); opacity: 1; } }
.chest-rarity-tag { font-size: 0.82rem; font-weight: 900; letter-spacing: 0.18em; color: var(--rar); text-transform: uppercase;
    text-shadow: 0 0 12px var(--rar); animation: chest-tag 0.5s ease both 0.15s; }
@keyframes chest-tag { 0% { opacity: 0; transform: translateY(-8px); letter-spacing: 0.5em; } 100% { opacity: 1; transform: none; } }
.chest-reward-glyph { font-size: clamp(3.4rem, 18vw, 5rem); line-height: 1; color: var(--rar); display: flex;
    filter: drop-shadow(0 0 18px var(--rar)); animation: chest-glyph 2.4s ease-in-out infinite; }
.chest-reward-glyph svg { width: 1em; height: 1em; }
@keyframes chest-glyph { 0%, 100% { transform: translateY(0) rotate(-2deg); } 50% { transform: translateY(-6px) rotate(2deg); } }
.chest-reward-name { font-size: clamp(1.2rem, 5.5vw, 1.5rem); font-weight: 900; color: #fff; text-shadow: 0 2px 10px rgba(0,0,0,0.6); }
.chest-reward-sub { font-size: 0.85rem; }
.chest-reward-sig { font-size: 0.82rem; font-weight: 800; color: var(--rar, #ffd75e); text-shadow: 0 0 12px var(--rar, #ffd75e); margin-top: 2px; max-width: 260px; }
.chest-badge-drop { position: relative; z-index: 1; display: inline-flex; align-items: center; gap: 10px; margin: 12px auto 0; padding: 8px 14px; border-radius: 999px; background: rgba(255, 215, 94, 0.12); border: 1px solid rgba(255, 215, 94, 0.5); box-shadow: 0 0 22px rgba(255, 215, 94, 0.28); animation: chest-badge-pop 0.5s cubic-bezier(0.2, 1.4, 0.4, 1) both; }
.chest-badge-drop-icon { font-size: 1.5rem; filter: drop-shadow(0 0 8px rgba(255, 215, 94, 0.7)); }
.chest-badge-drop-text { display: flex; flex-direction: column; line-height: 1.15; text-align: left; }
.chest-badge-drop-text strong { font-size: 0.7rem; letter-spacing: 0.08em; text-transform: uppercase; color: #ffd75e; }
.chest-badge-drop-text span { font-size: 0.95rem; font-weight: 800; color: #fff; }
@keyframes chest-badge-pop { from { opacity: 0; transform: scale(0.7) translateY(8px); } to { opacity: 1; transform: scale(1) translateY(0); } }
.chest-modal-actions { position: relative; z-index: 1; display: flex; gap: 10px; justify-content: center; flex-wrap: wrap; margin-top: 6px; }
.chest-modal-actions .button, .chest-modal-actions .pill { min-width: 130px; }

/* ── Store credit page ─────────────────────────────────────────────────────────────────────────────── */
.credit-balance { position: relative; overflow: hidden; display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-top: 6px;
    padding: 16px 18px; border-radius: 16px;
    background: linear-gradient(135deg, rgba(255,215,94,0.22), rgba(240,160,40,0.12) 58%, rgba(120,86,10,0.2));
    border: 1px solid rgba(255,215,94,0.5); box-shadow: 0 6px 20px rgba(240,160,40,0.18), inset 0 1px 0 rgba(255,255,255,0.16); }
.credit-balance::after { content: ""; position: absolute; inset: 0; pointer-events: none;
    background: linear-gradient(115deg, transparent 30%, rgba(255,255,255,0.08) 50%, transparent 70%); transform: translateX(-140%); animation: coinShine 5s ease-in-out infinite; }
.credit-balance-label { font-weight: 800; color: #ffe9a8; letter-spacing: 0.04em; text-transform: uppercase; font-size: 0.76rem; }
.credit-balance-amount { font-size: clamp(1.8rem, 7vw, 2.4rem); font-weight: 900; color: #ffd75e; text-shadow: 0 2px 8px rgba(240,160,40,0.4); }
/* Bright store-credit HERO — sells the top-up at a glance. */
.credit-hero { position: relative; overflow: hidden;
    /* Single smooth top glow fading into the dark base — two opposing corner radials used to cross in the
       middle and read as a faint vertical seam. */
    background: radial-gradient(160% 130% at 28% -25%, rgba(255,205,80,0.17), rgba(20,16,9,0.92) 62%);
    border: 1px solid rgba(255,215,94,0.4); }
.credit-hero-glow { position: absolute; top: -40%; right: -20%; width: 60%; height: 140%; pointer-events: none; z-index: 0;
    background: radial-gradient(circle, rgba(255,207,74,0.28), transparent 65%); animation: creditHeroGlow 5s ease-in-out infinite; }
@keyframes creditHeroGlow { 0%,100% { opacity: 0.6; } 50% { opacity: 1; } }
.credit-hero-top { position: relative; z-index: 1; display: flex; align-items: center; gap: 14px; }
.credit-hero-coin { font-size: 2.8rem; line-height: 1; flex: none; filter: drop-shadow(0 3px 6px rgba(240,160,40,0.6)); animation: coinBob 2.6s ease-in-out infinite; }
.credit-hero-copy { min-width: 0; }
.credit-hero-title { margin: 0; font-size: clamp(1.35rem, 6vw, 1.85rem); font-weight: 900; color: #fff; letter-spacing: -0.01em; }
.credit-hero-sub { margin: 4px 0 0; font-size: 0.9rem; color: #e8dcc4; }
.credit-hero-sub strong { color: #ffd75e; }
.credit-perks { position: relative; z-index: 1; display: grid; grid-template-columns: repeat(auto-fit, minmax(130px, 1fr)); gap: 8px; margin-top: 14px; }
.credit-perk { display: flex; flex-direction: column; gap: 1px; padding: 8px 10px; border-radius: 11px; font-size: 0.72rem; color: #c9bea6;
    background: rgba(255,255,255,0.05); border: 1px solid rgba(255,215,94,0.18); }
.credit-perk b { font-size: 0.86rem; color: #ffe6a8; }
.credit-presets { display: grid; grid-template-columns: repeat(auto-fit, minmax(96px, 1fr)); gap: 8px; margin: 4px 0 12px; }
/* Featured "Popular" tier — a gold ring + ribbon to steer the choice. */
.credit-chip.is-featured { border-color: rgba(255,215,94,0.7); box-shadow: 0 0 0 1px rgba(255,215,94,0.5) inset, 0 4px 16px rgba(240,160,40,0.3); padding-top: 20px; }
.credit-chip-flag { position: absolute; top: 0; left: 0; right: 0; padding: 2px 0; font-size: 0.6rem; font-weight: 900; letter-spacing: 0.06em;
    color: #2a1400; background: linear-gradient(180deg, #ffe08a, #ffbf3c); border-radius: 13px 13px 0 0; }
/* ── THE PACKAGE BANNER ─────────────────────────────────────────────────
   GOLD, not purple. The whole Den is gold and ember — the wolf, the coin, every primary button, the Arbiter
   banner — and a violet offer read like a different product bolted onto the side. This is the store selling
   something, so it should look like the store.

   And it MOVES: a slow sheen crosses it, the item bobs, the glow breathes. A static rectangle is a thing the
   eye files as furniture within a day. */
.pkgb { position: relative; overflow: hidden; display: flex; align-items: center; gap: 12px;
    padding: 12px 13px; margin: 0 0 12px; border-radius: 18px; text-decoration: none; color: #f7ecd2;
    background:
        radial-gradient(120% 150% at 88% 0%, rgba(255,215,94,0.26), transparent 60%),
        radial-gradient(90% 120% at 0% 100%, rgba(243,120,40,0.16), transparent 62%),
        linear-gradient(180deg, #2a2012, #17110a);
    border: 1px solid rgba(255,215,94,0.60);
    box-shadow: 0 0 0 1px rgba(255,215,94,0.14), 0 12px 34px rgba(0,0,0,0.5), 0 0 28px rgba(243,178,58,0.14);
    transition: transform .12s ease, box-shadow .12s ease; }
.pkgb:hover { transform: translateY(-2px);
    box-shadow: 0 0 0 1px rgba(255,215,94,0.3), 0 16px 40px rgba(0,0,0,0.55), 0 0 44px rgba(243,178,58,0.3); }
/* Wide and slow, so it reads as light moving over gold rather than as a loading shimmer. */
.pkgb::after { content: ""; position: absolute; inset: 0; pointer-events: none;
    background: linear-gradient(105deg, transparent 38%, rgba(255,235,170,0.16) 50%, transparent 62%);
    transform: translateX(-130%); animation: pkgbSheen 5.5s ease-in-out 1s infinite; }
@keyframes pkgbSheen { 0% { transform: translateX(-130%); } 60%,100% { transform: translateX(130%); } }
.pkgb-art { position: relative; flex: 0 0 auto; display: grid; place-items: center; }
.pkgb-glow { position: absolute; width: 135%; height: 135%; border-radius: 50%; pointer-events: none;
    background: radial-gradient(circle, rgba(255,215,94,0.34) 0%, rgba(243,178,58,0.12) 45%, transparent 70%);
    animation: pkgbPulse 3.2s ease-in-out infinite; }
@keyframes pkgbPulse { 0%,100% { transform: scale(0.9); opacity: .65; } 50% { transform: scale(1.08); opacity: 1; } }
.pkgb-stand { position: relative; animation: pkgbBob 4.2s ease-in-out infinite; }
@keyframes pkgbBob { 0%,100% { transform: translateY(0); } 50% { transform: translateY(-3px); } }
.pkgb-deco { display: block; width: 100%; height: 100%; object-fit: contain;
    filter: drop-shadow(0 6px 9px rgba(0,0,0,0.55)); }
.pkgb-pet { position: absolute; object-fit: contain; transform: translate(-50%, -100%);
    filter: drop-shadow(0 2px 3px rgba(0,0,0,0.45)); }
.pkgb-body { position: relative; z-index: 1; min-width: 0; flex: 1 1 auto; }
.pkgb-kick, .pkgb-preview { display: inline-flex; align-items: center; gap: 4px; font-size: .6rem;
    font-weight: 900; letter-spacing: .14em; text-transform: uppercase; color: #ffd75e; }
.pkgb-preview { color: #ff9f4a; }
.pkgb-body b { display: block; font-size: 1.04rem; line-height: 1.15; color: #fff6de;
    text-shadow: 0 1px 10px rgba(255,215,94,0.28); }
.pkgb-body em { display: block; margin-top: 2px; font-style: normal; font-size: .74rem; line-height: 1.35;
    color: #cdbb96; }
.pkgb-gets { display: flex; flex-wrap: wrap; gap: 4px 10px; margin-top: 6px; }
.pkgb-gets i { font-style: normal; font-size: .68rem; color: #cdbb96; }
.pkgb-gets i b { display: inline; font-size: .78rem; color: #ffd75e; }
.pkgb-cta { position: relative; z-index: 1; flex: 0 0 auto; display: grid; justify-items: center; gap: 1px;
    padding: 9px 13px; border-radius: 12px; color: #3a2c08;
    background: linear-gradient(180deg, #ffe488, #f3b23a);
    box-shadow: 0 3px 0 #b57f22, 0 5px 16px rgba(243,178,58,0.4); }
.pkgb-cta b { font-size: 1.04rem; font-weight: 900; }
.pkgb-cta i { font-style: normal; font-size: .62rem; font-weight: 800; }
@media (max-width: 430px) {
    .pkgb { gap: 9px; padding: 10px; }
    .pkgb-body em { display: none; }
    .pkgb-cta { padding: 8px 10px; }
    .pkgb-cta b { font-size: .94rem; }
}

/* ── THE PACKAGE CARD ────────────────────────────────────────────────────
   The full pitch, in the same gold. Built as an advertisement: the item drawn working, the numbers in large
   type, three lines on what it does. pkgc- prefixed so nothing collides with the plain credit chips below. */
.credit-pkgs { display: grid; gap: 12px; margin-bottom: 6px; }
.pkgc { position: relative; overflow: hidden; border-radius: 20px; padding: 16px;
    background:
        radial-gradient(110% 90% at 85% 0%, rgba(255,215,94,0.24), transparent 62%),
        radial-gradient(90% 80% at 0% 100%, rgba(243,120,40,0.16), transparent 60%),
        linear-gradient(180deg, #2a2012, #16110b);
    border: 1px solid rgba(255,215,94,0.55);
    box-shadow: 0 14px 40px rgba(0,0,0,0.5), 0 0 30px rgba(243,178,58,0.12); }
.pkgc.is-on { border-color: rgba(255,215,94,0.95);
    box-shadow: 0 0 0 1px rgba(255,215,94,0.5), 0 18px 48px rgba(243,178,58,0.3); }
.pkgc::after { content: ""; position: absolute; inset: 0; pointer-events: none;
