.pkgc-stand { position: relative; animation: pkgcBob 4.6s ease-in-out infinite; }
@keyframes pkgcBob { 0%,100% { transform: translateY(0); } 50% { transform: translateY(-4px); } }
.pkgc-deco { display: block; width: 100%; height: 100%; object-fit: contain;
