.pkgc-gets { position: relative; z-index: 1; display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px;
    margin-top: 14px; }
.pkgc-get { display: grid; justify-items: center; text-align: center; gap: 1px; padding: 10px 6px;
    border-radius: 14px; background: rgba(255,215,94,0.07); border: 1px solid rgba(255,215,94,0.24); }
.pkgc-get-ico { display: grid; place-items: center; height: 34px; }
.pkgc-get-ico img { max-width: 34px; max-height: 34px; object-fit: contain; }
.pkgc-get b { font-size: 1.26rem; line-height: 1.1; color: #ffd75e; }
.pkgc-get em { font-style: normal; font-size: 0.72rem; font-weight: 700; color: #f7ecd2; }
