.pkgc-do { display: flex; gap: 9px; align-items: flex-start; }
.pkgc-do-ico { flex: 0 0 auto; display: grid; place-items: center; width: 26px; height: 26px;
    border-radius: 8px; color: #ffd75e; font-size: 15px;
