.pkgc-cta { position: relative; z-index: 1; display: flex; align-items: center; justify-content: center;
    gap: 7px; width: 100%; margin-top: 14px; padding: 14px; border: 0; border-radius: 14px; cursor: pointer;
    font-family: var(--font-display); font-size: 1.04rem; font-weight: 900; color: #3a2c08;
    background: linear-gradient(180deg, #ffe488, #f3b23a);
    box-shadow: 0 4px 0 #b57f22, 0 6px 20px rgba(243,178,58,0.42); }
