}
.credit-chip { position: relative; }
.credit-chip { display: flex; flex-direction: column; align-items: center; gap: 3px; padding: 12px 6px; border-radius: 14px; cursor: pointer;
    background: linear-gradient(180deg, rgba(255,255,255,0.06), rgba(0,0,0,0.25)); border: 1px solid rgba(255,255,255,0.14);
    transition: transform 0.12s ease, border-color 0.12s ease, box-shadow 0.12s ease; }
.credit-chip:hover { transform: translateY(-2px); border-color: rgba(255,215,94,0.6); box-shadow: 0 6px 16px rgba(0,0,0,0.4); }
.credit-chip.is-active { background: linear-gradient(180deg, rgba(255,215,94,0.3), rgba(240,160,40,0.14)); border-color: #ffd75e; box-shadow: 0 0 0 1px #ffd75e inset, 0 4px 16px rgba(240,160,40,0.35); }
.credit-chip-usd { font-weight: 900; font-size: 1.12rem; color: #ffffff; text-shadow: 0 1px 2px rgba(0,0,0,0.55); }
.credit-chip.is-active .credit-chip-usd { color: #fff3c9; }
.credit-chip-coins { font-size: 0.72rem; font-weight: 800; color: #ffcf7a; }
.credit-custom { display: flex; flex-direction: column; gap: 5px; margin-bottom: 12px; }
.credit-custom-field { display: inline-flex; align-items: center; gap: 6px; padding: 10px 14px; border-radius: 12px;
    background: rgba(0,0,0,0.35); border: 1px solid rgba(255,215,94,0.28); max-width: 180px; font-weight: 800; color: #f5ead2; }
.credit-custom-field input { flex: 1; min-width: 0; background: transparent; border: none; color: #f5ead2; font: inherit; outline: none; }
.credit-custom-field input::placeholder { color: #8a8272; }
.credit-summary { display: flex; flex-direction: column; gap: 7px; margin: 4px 0 14px; padding: 14px 16px; border-radius: 14px;
    background: linear-gradient(180deg, rgba(255,215,94,0.07), rgba(255,255,255,0.02)); border: 1px solid rgba(255,215,94,0.22); }
.credit-summary > div { display: flex; align-items: center; justify-content: space-between; gap: 12px; font-size: 0.92rem; color: #e8ddc8; }
.credit-summary > div strong { color: #ffffff; }
/* The line that names the thing you are buying. Gold and first, because "Credit added $5.00" alone reads
   identically whether or not the package is attached — which is exactly how a member paid $25 for a top-up
   believing the advertised item came with it. */
/* Why a chat message was refused — sits above the feed, brief and quiet. */
.social-note { margin: 0 0 8px; padding: 7px 11px; border-radius: 10px; font-size: 0.78rem; line-height: 1.4;
    color: #ffd9b0; background: rgba(255,150,60,0.10); border: 1px solid rgba(255,150,60,0.28); }
.credit-summary-item { border-bottom: 1px solid rgba(255,215,110,0.22); padding-bottom: 7px; margin-bottom: 1px; }
.credit-summary-item span { color: #ffd75e; font-weight: 900; }
.credit-summary-item strong { color: #ffd75e !important; text-transform: uppercase; font-size: 0.72rem; letter-spacing: .6px; }
.credit-nopkg { margin: -6px 0 12px; padding: 9px 12px; border-radius: 11px; font-size: 0.78rem; line-height: 1.45;
    color: #f0e0bb; background: rgba(255,215,110,0.08); border: 1px solid rgba(255,215,110,0.26); }
.credit-summary-total { padding-top: 10px; margin-top: 2px; border-top: 1px solid rgba(255,215,94,0.25); font-size: 1.15rem; font-weight: 900; color: #ffffff; }
.credit-summary-total strong { color: #ffd75e; }
.credit-card-field { min-height: 52px; padding: 6px; border-radius: 12px; background: #15161c; border: 1px solid rgba(255,215,94,0.22); margin-bottom: 12px; }
.credit-buy { width: 100%; font-weight: 900; font-size: 1.02rem; padding: 13px; border-radius: 12px; border: none; cursor: pointer;
    color: #3a2c04; background: linear-gradient(135deg, #ffe9a8, #ffcf4a 46%, #f2a93b);
    box-shadow: 0 4px 16px rgba(240,160,40,0.45), inset 0 1px 0 rgba(255,255,255,0.5); transition: transform 0.1s ease; }
.credit-buy:disabled { opacity: 0.5; cursor: default; box-shadow: none; }
.credit-buy:not(:disabled):active { transform: scale(0.98); }
.credit-done { text-align: center; }
.credit-qr { display: flex; flex-direction: column; align-items: center; gap: 10px; text-align: center; }
.credit-qr img { border-radius: 12px; background: #fff; padding: 8px; }
.credit-history { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 2px; }
.credit-history li { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 8px 4px;
    border-bottom: 1px solid rgba(255,255,255,0.07); font-size: 0.9rem; }
.credit-history li:last-child { border-bottom: none; }
.credit-plus { color: #7cffb2; font-weight: 800; }
.credit-minus { color: #ffb0a0; font-weight: 800; }
.game-nav-gold-plus { display: inline-grid; place-items: center; width: 1.15em; height: 1.15em; margin-left: 2px; border-radius: 50%;
    background: rgba(255,215,94,0.25); color: #ffe9a8; font-weight: 900; font-size: 0.85em; line-height: 1; }
.shop-credit-line strong { color: #7cffb2; }
.shop-credit-toggle { display: flex; align-items: center; gap: 8px; margin: 10px 0; padding: 10px 12px; border-radius: 10px;
    background: rgba(124,255,178,0.08); border: 1px solid rgba(124,255,178,0.3); cursor: pointer; font-size: 0.9rem; }
.shop-credit-toggle input { width: 18px; height: 18px; accent-color: #2ecc71; }

/* "Not enough coins → buy store credit" CTA — bright + tappable, never reads as a disabled state. */
.coin-cta { display: inline-flex; align-items: center; gap: 6px; padding: 3px 10px; border-radius: 999px;
    background: linear-gradient(120deg, rgba(255,215,94,0.22), rgba(255,140,60,0.22)); border: 1px solid rgba(255,215,94,0.65);
    color: #ffe9a8; font-size: 0.74rem; font-weight: 800; letter-spacing: 0.01em; text-decoration: none; line-height: 1.5;
    box-shadow: 0 1px 6px rgba(255,150,40,0.25); transition: transform 0.1s ease, box-shadow 0.1s ease; white-space: nowrap; }
.coin-cta:hover { transform: translateY(-1px); box-shadow: 0 3px 12px rgba(255,150,40,0.45); }
.coin-cta-price { opacity: 0.85; }
.coin-cta-get { background: rgba(0,0,0,0.28); padding: 0 7px; border-radius: 999px; }
/* Rotating boss reward-item card (cycles every 3s when there's more than one drop). */
.boss-reward-rotate { animation: bossRewardFade 0.45s ease; }
@keyframes bossRewardFade { from { opacity: 0; transform: translateY(4px); } to { opacity: 1; transform: none; } }
.boss-reward-dots { display: flex; gap: 5px; margin-top: 6px; }
.boss-reward-dots span { width: 6px; height: 6px; border-radius: 50%; background: rgba(255,255,255,0.22); transition: background 0.2s ease; }
.boss-reward-dots span.is-on { background: #ffd75e; }

/* ── Top HUD strip: dopamine coin chip + the rank-progress nudge, one slim row (replaces the nav gold pill) ── */
.hud-strip { display: flex; align-items: center; gap: 8px; padding: 6px 12px;
    background: linear-gradient(90deg, rgba(255,215,94,0.06), rgba(255,215,94,0.02));
    border-bottom: 1px solid rgba(255,215,94,0.18); }
.hud-strip .reward-nudge { flex: 1 1 auto; min-width: 0; gap: 8px; padding: 2px 4px; background: none; border-bottom: none; }
.hud-strip .reward-nudge:hover { background: none; }
/* Bar-forward on mobile: the progress bar fills the space (no gift/rank label eating it), XP-to-go on the right. */
.hud-strip .reward-nudge-bar { flex: 1 1 auto; height: 9px; min-width: 46px; }
.hud-strip .reward-nudge-togo { font-size: 0.82rem; }
/* The coin chip — a shiny gold pill that catches the eye, with a punchy round "+" to buy more. */
.coin-hud { position: relative; flex: 0 0 auto; display: inline-flex; align-items: center; gap: 6px; overflow: hidden;
    padding: 4px 5px 4px 11px; border-radius: 999px; text-decoration: none; font-weight: 900; color: #241900;
    background: linear-gradient(135deg, #ffe9a8, #ffcf4a 46%, #f2a93b);
    border: 1px solid rgba(255,255,255,0.55);
    box-shadow: 0 2px 9px rgba(240,160,40,0.5), inset 0 1px 0 rgba(255,255,255,0.65); }
.coin-hud::after { content: ""; position: absolute; inset: 0; pointer-events: none;
    background: linear-gradient(115deg, transparent 42%, rgba(255,255,255,0.8) 50%, transparent 58%);
    transform: translateX(-130%); animation: coinShine 3.8s ease-in-out infinite; }
@keyframes coinShine { 0%, 72% { transform: translateX(-130%); } 90%, 100% { transform: translateX(130%); } }
.coin-hud-icon { font-size: 1rem; line-height: 1; filter: drop-shadow(0 1px 1px rgba(0,0,0,0.25)); animation: coinBob 2.6s ease-in-out infinite; }
@keyframes coinBob { 0%, 100% { transform: translateY(0) rotate(0); } 50% { transform: translateY(-1.5px) rotate(-9deg); } }
.hud-strip .coin-hud, .hud-strip .coin-hud .coin-hud-amt { color: #241900; }
.coin-hud-amt { font-size: 0.92rem; font-weight: 900; letter-spacing: 0.01em; }
.coin-hud-plus { display: inline-grid; place-items: center; width: 21px; height: 21px; border-radius: 50%; font-size: 1.05rem; font-weight: 900; line-height: 1;
    color: #fff; background: linear-gradient(135deg, #ff8a44, #e8431f);
    box-shadow: 0 1px 4px rgba(230,60,20,0.6), inset 0 1px 0 rgba(255,255,255,0.45); animation: coinPlusPulse 2.4s ease-in-out infinite; }
/* The "+" gently pulses to invite a top-up. */
@keyframes coinPlusPulse { 0%, 100% { transform: scale(1); box-shadow: 0 1px 4px rgba(230,60,20,0.6), inset 0 1px 0 rgba(255,255,255,0.45); } 50% { transform: scale(1.12); box-shadow: 0 0 10px rgba(255,120,40,0.85), inset 0 1px 0 rgba(255,255,255,0.45); } }
.coin-hud:active { transform: scale(0.97); }
/* Low balance → the whole chip breathes an amber glow to nudge a top-up. */
.coin-hud.is-low { animation: coinLowGlow 1.6s ease-in-out infinite; }
@keyframes coinLowGlow { 0%, 100% { box-shadow: 0 2px 9px rgba(240,160,40,0.5), inset 0 1px 0 rgba(255,255,255,0.65); } 50% { box-shadow: 0 0 16px 2px rgba(255,150,40,0.95), inset 0 1px 0 rgba(255,255,255,0.65); } }
.coin-hud.is-low .coin-hud-plus { animation-duration: 1.1s; }
.boss2-sub { font-size: 0.78rem; text-align: center; margin: 2px 0 8px; }

/* Active-heroes mini cards: dressed in each member's signature color + their equipped profile background,
   so they match the on-stage nameplate. "You" keeps its gold treatment. */
.herochip.has-glow:not(.is-you) { border-color: color-mix(in srgb, var(--glow) 60%, rgba(255,255,255,0.14));
    box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--glow) 40%, transparent), 0 0 12px -4px var(--glow); }
.herochip.has-bg { position: relative; }
.herochip.has-bg .herochip-name, .herochip.has-bg .herochip-meta { text-shadow: 0 1px 3px rgba(0,0,0,0.85); }
.herochip.is-link.has-glow:not(.is-you):hover { border-color: color-mix(in srgb, var(--glow) 85%, transparent); }

/* Fortune-wheel icon (react-icons FaDharmachakra) that replaced the ferris-wheel emoji for the Spin. */
